PathwayData.put("data/reading_writing/units/L02U1.json",{"strand":"reading_writing","level":2,"cefr":"A1b","unit":1,"theme":"Friends and Feelings","essential_question":"How can we be a good friend?","schema_version":"1.0","core_words":["kind","share","smile","sad","angry","scared","excited","tired","together","sorry","thank","game","laugh","care"],"recycled_words":["happy","friend","help","play","wind","tree","big","small","special","favorite","fix","family","funny"],"rubrics":[{"id":"RW-RUBRIC-5T","title":"Analytic writing rubric","traits":[{"name":"Ideas","name_ar":"الأفكار","bands":[{"score":4,"descriptor":"My ideas are clear, interesting and fully developed with strong details.","descriptor_ar":"أفكاري واضحة وممتعة ومدعومة بتفاصيل قوية."},{"score":3,"descriptor":"My ideas are clear and have enough details.","descriptor_ar":"أفكاري واضحة ومعها تفاصيل كافية."},{"score":2,"descriptor":"My main idea is there but needs more details.","descriptor_ar":"فكرتي الرئيسية موجودة لكنها تحتاج إلى تفاصيل أكثر."},{"score":1,"descriptor":"My ideas are unclear or very few.","descriptor_ar":"أفكاري غير واضحة أو قليلة جدًا."}]},{"name":"Organization","name_ar":"التنظيم","bands":[{"score":4,"descriptor":"Clear beginning, middle and end; ideas flow with linking words.","descriptor_ar":"بداية ووسط ونهاية واضحة، والأفكار مترابطة بكلمات الربط."},{"score":3,"descriptor":"Clear order with some linking words.","descriptor_ar":"ترتيب واضح مع بعض كلمات الربط."},{"score":2,"descriptor":"Some order, but parts are mixed up.","descriptor_ar":"يوجد بعض الترتيب لكن بعض الأجزاء غير مرتبة."},{"score":1,"descriptor":"Ideas are not in order.","descriptor_ar":"الأفكار غير مرتبة."}]},{"name":"Vocabulary","name_ar":"المفردات","bands":[{"score":4,"descriptor":"I use exact, varied words, including new unit words, correctly.","descriptor_ar":"أستخدم كلمات دقيقة ومتنوعة، منها كلمات الوحدة الجديدة، بشكل صحيح."},{"score":3,"descriptor":"I use some new words correctly.","descriptor_ar":"أستخدم بعض الكلمات الجديدة بشكل صحيح."},{"score":2,"descriptor":"I use simple words; some are repeated or wrong.","descriptor_ar":"أستخدم كلمات بسيطة، وبعضها مكرر أو غير صحيح."},{"score":1,"descriptor":"I use very few words; the meaning is hard to understand.","descriptor_ar":"أستخدم كلمات قليلة جدًا ويصعب فهم المعنى."}]},{"name":"Sentence fluency","name_ar":"سلاسة الجمل","bands":[{"score":4,"descriptor":"My sentences are complete, varied in length and easy to read aloud.","descriptor_ar":"جملي كاملة ومتنوعة الطول وسهلة القراءة بصوت عالٍ."},{"score":3,"descriptor":"Most sentences are complete, with some variety.","descriptor_ar":"معظم جملي كاملة مع بعض التنويع."},{"score":2,"descriptor":"Many sentences are short or start the same way.","descriptor_ar":"كثير من جملي قصيرة أو تبدأ بالطريقة نفسها."},{"score":1,"descriptor":"Sentences are incomplete or run together.","descriptor_ar":"جملي ناقصة أو متداخلة."}]},{"name":"Conventions","name_ar":"قواعد الكتابة","bands":[{"score":4,"descriptor":"Capitals, punctuation, spelling and grammar are almost always correct.","descriptor_ar":"الحروف الكبيرة وعلامات الترقيم والإملاء والقواعد صحيحة دائمًا تقريبًا."},{"score":3,"descriptor":"A few mistakes that do not affect meaning.","descriptor_ar":"أخطاء قليلة لا تؤثر في المعنى."},{"score":2,"descriptor":"Several mistakes; the meaning is sometimes unclear.","descriptor_ar":"عدة أخطاء، والمعنى أحيانًا غير واضح."},{"score":1,"descriptor":"Many mistakes make it hard to read.","descriptor_ar":"أخطاء كثيرة تجعل القراءة صعبة."}]}]}],"lessons":[{"id":"RW-L02-U1-LS1","title":"Word Power: Friends and Feelings","lesson_type":"vocabulary","objectives":["read and say 14 words about friends and feelings and 2 Tier 2 words (feeling, understand)","match feeling words with their synonyms (happy/glad, scared/afraid, angry/mad)","use feeling words in sentences about themselves and their friends"],"objectives_ar":["قراءة ونطق 14 كلمة عن الأصدقاء والمشاعر وكلمتين أكاديميتين (feeling, understand).","مطابقة كلمات المشاعر مع مرادفاتها.","استخدام كلمات المشاعر في جمل عن أنفسهم وأصدقائهم."],"success_criteria":["I can read and say the feeling words.","I can find a word with the same meaning (a synonym).","I can say how I feel and why."],"success_criteria_ar":["أستطيع قراءة كلمات المشاعر ونطقها.","أستطيع إيجاد كلمة بالمعنى نفسه (مرادف).","أستطيع قول بماذا أشعر ولماذا."],"map_area":"Vocabulary: Acquisition and Use","vocabulary":[{"word":"kind","pos":"adjective","ipa":"/kaɪnd/","definition":"nice and helpful to other people","arabic":"لطيف / طيب","example":"It is kind to help a new student.","image_id":"IMG-RW-L02-U1-LS1-V01","audio_id":"AUD-RW-L02-U1-LS1-V01","tier":"core"},{"word":"share","pos":"verb","ipa":"/ʃɛr/","definition":"to give part of what you have to others","arabic":"يشارك / يقتسم","example":"Badr shares his dates with me.","image_id":"IMG-RW-L02-U1-LS1-V02","audio_id":"AUD-RW-L02-U1-LS1-V02","tier":"core"},{"word":"smile","pos":"verb","ipa":"/smaɪl/","definition":"to make a happy face with your mouth","arabic":"يبتسم","example":"Smile at your new friend.","image_id":"IMG-RW-L02-U1-LS1-V03","audio_id":"AUD-RW-L02-U1-LS1-V03","tier":"core"},{"word":"sad","pos":"adjective","ipa":"/sæd/","definition":"not happy","arabic":"حزين","example":"Reem is sad because her cat is sick.","image_id":"IMG-RW-L02-U1-LS1-V04","audio_id":"AUD-RW-L02-U1-LS1-V04","tier":"core"},{"word":"angry","pos":"adjective","ipa":"/ˈæŋɡri/","definition":"feeling very upset with someone or something","arabic":"غاضب","example":"Faris is angry because his tower fell.","image_id":"IMG-RW-L02-U1-LS1-V05","audio_id":"AUD-RW-L02-U1-LS1-V05","tier":"core"},{"word":"scared","pos":"adjective","ipa":"/skɛrd/","definition":"afraid","arabic":"خائف","example":"The kitten is scared of the dog.","image_id":"IMG-RW-L02-U1-LS1-V06","audio_id":"AUD-RW-L02-U1-LS1-V06","tier":"core"},{"word":"excited","pos":"adjective","ipa":"/ɪkˈsaɪtɪd/","definition":"very happy because something good will happen","arabic":"متحمس","example":"I am excited about the trip.","image_id":"IMG-RW-L02-U1-LS1-V07","audio_id":"AUD-RW-L02-U1-LS1-V07","tier":"core"},{"word":"tired","pos":"adjective","ipa":"/taɪrd/","definition":"needing to rest or sleep","arabic":"متعب","example":"After football, I am tired.","image_id":"IMG-RW-L02-U1-LS1-V08","audio_id":"AUD-RW-L02-U1-LS1-V08","tier":"core"},{"word":"together","pos":"adverb","ipa":"/təˈɡɛðər/","definition":"with each other","arabic":"معًا","example":"We build a sandcastle together.","image_id":"IMG-RW-L02-U1-LS1-V09","audio_id":"AUD-RW-L02-U1-LS1-V09","tier":"core"},{"word":"sorry","pos":"adjective","ipa":"/ˈsɑri/","definition":"a word you say when you did something wrong","arabic":"آسف","example":"I am sorry I broke your pencil.","image_id":"IMG-RW-L02-U1-LS1-V10","audio_id":"AUD-RW-L02-U1-LS1-V10","tier":"core"},{"word":"thank","pos":"verb","ipa":"/θæŋk/","definition":"to say you are happy for help or a gift","arabic":"يشكر","example":"Thank your teacher for the book.","image_id":"IMG-RW-L02-U1-LS1-V11","audio_id":"AUD-RW-L02-U1-LS1-V11","tier":"core"},{"word":"game","pos":"noun","ipa":"/ɡeɪm/","definition":"an activity you play with rules","arabic":"لعبة","example":"Let's play a game!","image_id":"IMG-RW-L02-U1-LS1-V12","audio_id":"AUD-RW-L02-U1-LS1-V12","tier":"core"},{"word":"laugh","pos":"verb","ipa":"/læf/","definition":"to make happy sounds because something is funny","arabic":"يضحك","example":"We laugh at the funny story.","image_id":"IMG-RW-L02-U1-LS1-V13","audio_id":"AUD-RW-L02-U1-LS1-V13","tier":"core"},{"word":"care","pos":"verb","ipa":"/kɛr/","definition":"to feel that someone is important and help them","arabic":"يهتم بـ","example":"Good friends care about each other.","image_id":"IMG-RW-L02-U1-LS1-V14","audio_id":"AUD-RW-L02-U1-LS1-V14","tier":"core"},{"word":"feeling","pos":"noun","ipa":"/ˈfilɪŋ/","definition":"something you feel inside, like happy or sad","arabic":"شعور","example":"Excited is a happy feeling.","image_id":"IMG-RW-L02-U1-LS1-V15","audio_id":"AUD-RW-L02-U1-LS1-V15","tier":"tier2"},{"word":"understand","pos":"verb","ipa":"/ˌʌndərˈstænd/","definition":"to know what something means or how someone feels","arabic":"يفهم","example":"I understand how you feel.","image_id":"IMG-RW-L02-U1-LS1-V16","audio_id":"AUD-RW-L02-U1-LS1-V16","tier":"tier2"}],"explanation":{"text":"**Feeling words** tell how a person feels inside: *happy, sad, angry, scared, excited, tired*.\n\nA **synonym** is a word with the **same or almost the same meaning**. Synonyms help us understand new words and make our writing more interesting.\n\nSome feeling synonyms: **happy = glad**, **sad = unhappy**, **scared = afraid**, **angry = mad**, **tired = sleepy**.\n\nLook for clues in faces and actions: a smile → happy; tears → sad; a red face → angry; hiding → scared.","examples":["**happy** → glad: *I am glad you are here.*","**sad** → unhappy: *The boy is unhappy because he lost his ball.*","**scared** → afraid: *Lama is afraid of the dark.*","**angry** → mad: *Faris is mad because his brother took his toy.*","**tired** → sleepy: *After a long day, I feel sleepy.*","**excited** → can't wait: *Eid is tomorrow! I can't wait!*","Clue: *Her eyes are full of tears.* → she is **sad**.","Clue: *He jumps and claps.* → he is **excited**.","Clue: *She hides behind her mother.* → she is **scared**."],"common_errors":["✗ I am feel happy. → ✓ I feel happy. / I am happy. (Use **feel** OR **am**, not both.)","✗ He is boring. (when he feels bored) → ✓ He is bored. (*-ed* words tell how you feel.)","✗ I am exciting about the trip. → ✓ I am excited about the trip. (*excited* = how I feel.)","✗ She is angry from me. → ✓ She is angry with me. (Say **angry with** a person.)","✗ I am scary of dogs. → ✓ I am scared of dogs. (*scared of* = afraid of.)","✗ Sorry for I am late. → ✓ Sorry I am late. / I am sorry I am late. (No **for** before a full sentence.)","✗ We play together with each other. → ✓ We play together. (*together* already means with each other.)"],"arabic":"كلمات المشاعر تخبرنا بما يشعر به الشخص في داخله: سعيد، حزين، غاضب، خائف، متحمس، متعب.\n\nالمرادف (synonym) كلمة لها المعنى نفسه أو قريب منه، مثل happy = glad وscared = afraid.\n\nابحث عن الأدلة في الوجوه والأفعال: الابتسامة تعني السعادة، والدموع تعني الحزن، والاختباء يعني الخوف.\n\nانتبه: نقول I feel happy أو I am happy، ولا نقول I am feel happy. ونقول I am excited (أنا متحمس) لا exciting."},"video":{"script":[{"time":"00:00–00:15","narration":"How do you feel today? Happy? Sad? Let's learn feeling words!","on_screen":"Friends and Feelings","visual":"Saqr looks in a mirror and makes different faces."},{"time":"00:15–00:50","narration":"Happy… sad… angry… scared. Look at the faces!","on_screen":"happy · sad · angry · scared","visual":"Four children's faces appear; each glows as its word is said."},{"time":"00:50–01:20","narration":"Excited – jumping and clapping! Tired – yawning and sleepy.","on_screen":"excited · tired","visual":"Omar jumps with a kite; Sami yawns on the sofa."},{"time":"01:20–01:55","narration":"Synonyms are words with the same meaning. Happy… glad! Scared… afraid! Angry… mad!","on_screen":"happy = glad · scared = afraid · angry = mad","visual":"Pairs of word cards slide together and click."},{"time":"01:55–02:25","narration":"Good friends share, smile, laugh and care. They say sorry and thank you.","on_screen":"share · smile · laugh · care · sorry · thank you","visual":"Sami and Omar share a snack, laugh, and Sami says 'sorry' after bumping Omar."},{"time":"02:25–02:45","narration":"Every feeling is OK. Now tell a friend: How do you feel?","on_screen":"How do you feel?","visual":"Children in a circle point to feeling cards on a chart."}],"captions_ar":["بماذا تشعر اليوم؟ سعيد؟ حزين؟ لنتعلم كلمات المشاعر!","سعيد… حزين… غاضب… خائف. انظروا إلى الوجوه!","متحمس: يقفز ويصفق! متعب: يتثاءب ويشعر بالنعاس.","المرادفات كلمات لها المعنى نفسه: happy… glad! scared… afraid! angry… mad!","الأصدقاء الجيدون يتشاركون ويبتسمون ويضحكون ويهتمون، ويقولون آسف وشكرًا.","كل المشاعر مقبولة. والآن اسأل صديقك: بماذا تشعر؟"],"voice":"Narrator: American English, warm female teacher, speed 0.85, gentle and caring. Saqr: playful young male voice. Each feeling word is said with matching emotion."},"texts":[],"activities":[{"id":"RW-L02-U1-LS1-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Look at the clue. Choose the feeling word.","instructions_ar":"انظر إلى الدليل واختر كلمة الشعور.","items":[{"q":"Clue: *Her eyes are full of tears.* How does she feel?","answer":"sad","explanation":"Tears show sadness.","explanation_ar":"الدموع تدل على الحزن.","options":["excited","tired","sad","glad"],"dok":1,"skill":"feeling clues","stage":"controlled"},{"q":"Clue: *He jumps up and down and claps.* How does he feel?","answer":"excited","explanation":"Jumping and clapping show excitement.","explanation_ar":"القفز والتصفيق يدلان على الحماس.","options":["excited","sad","scared","tired"],"dok":1,"skill":"feeling clues","stage":"controlled"},{"q":"Clue: *She hides behind her mother.* How does she feel?","answer":"scared","explanation":"Hiding shows fear.","explanation_ar":"الاختباء يدل على الخوف.","options":["angry","happy","tired","scared"],"dok":1,"skill":"feeling clues","stage":"controlled"},{"q":"Clue: *He yawns and closes his eyes.* How does he feel?","answer":"tired","explanation":"Yawning shows tiredness.","explanation_ar":"التثاؤب يدل على التعب.","options":["tired","excited","angry","glad"],"dok":1,"skill":"feeling clues","stage":"controlled"},{"q":"Clue: *His face is red and he shouts.* How does he feel?","answer":"angry","explanation":"A red face and shouting show anger.","explanation_ar":"الوجه الأحمر والصراخ يدلان على الغضب.","options":["glad","angry","sleepy","kind"],"dok":1,"skill":"feeling clues","stage":"controlled"},{"q":"Clue: *Two friends tell a funny story and make happy sounds.* What do they do?","answer":"laugh","explanation":"Happy sounds at something funny = laugh.","explanation_ar":"يضحكان.","options":["cry","sleep","hide","laugh"],"dok":1,"skill":"action words","stage":"controlled"}]},{"id":"RW-L02-U1-LS1-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Choose the synonym (the word with the same meaning).","instructions_ar":"اختر المرادف (الكلمة بالمعنى نفسه).","items":[{"q":"*happy* means the same as ___.","answer":"glad","explanation":"Happy = glad.","explanation_ar":"happy = glad.","options":["mad","glad","afraid","sleepy"],"dok":1,"skill":"synonyms","stage":"guided"},{"q":"*scared* means the same as ___.","answer":"afraid","explanation":"Scared = afraid.","explanation_ar":"scared = afraid.","options":["glad","kind","afraid","excited"],"dok":1,"skill":"synonyms","stage":"guided"},{"q":"*angry* means the same as ___.","answer":"mad","explanation":"Angry = mad.","explanation_ar":"angry = mad.","options":["glad","mad","tired","sorry"],"dok":1,"skill":"synonyms","stage":"guided"},{"q":"*tired* means almost the same as ___.","answer":"sleepy","explanation":"Tired ≈ sleepy.","explanation_ar":"tired ≈ sleepy.","options":["excited","kind","afraid","sleepy"],"dok":1,"skill":"synonyms","stage":"guided"},{"q":"*sad* means the same as ___.","answer":"unhappy","explanation":"Sad = unhappy.","explanation_ar":"sad = unhappy.","options":["unhappy","glad","excited","kind"],"dok":1,"skill":"synonyms","stage":"guided"},{"q":"Which pair is NOT a pair of synonyms?","answer":"happy – sad","explanation":"Happy and sad are opposites.","explanation_ar":"happy وsad متضادتان.","options":["angry – mad","scared – afraid","happy – sad","happy – glad"],"dok":2,"skill":"synonyms vs. opposites","stage":"guided"}]},{"id":"RW-L02-U1-LS1-A3","type":"gap_fill","stage":"freer","instructions":"Freer practice: Use the word bank to complete each sentence.","instructions_ar":"استخدم بنك الكلمات لإكمال الجمل.","items":[{"q":"Good friends ________ their toys and snacks.","answer":"share","explanation":"Share = give part to others.","explanation_ar":"يتشاركون.","stage":"freer"},{"q":"I broke your pencil. I am ________.","answer":"sorry","explanation":"We say sorry when we did something wrong.","explanation_ar":"آسف.","stage":"freer"},{"q":"Omar and Sami play football ________ every day.","answer":"together","explanation":"Together = with each other.","explanation_ar":"معًا.","stage":"freer"},{"q":"A good friend will ________ how you feel.","answer":"understand","explanation":"Understand = know how someone feels.","explanation_ar":"يفهم.","stage":"freer"},{"q":"My grandmother is very ________. She helps everyone.","answer":"kind","explanation":"Kind = nice and helpful.","explanation_ar":"لطيفة.","stage":"freer"},{"q":"Excited is a happy ________.","answer":"feeling","explanation":"Excited is a feeling.","explanation_ar":"شعور.","stage":"freer"}]},{"id":"RW-L02-U1-LS1-A4","type":"open","stage":"production","instructions":"Writing: Write about YOUR feelings.","instructions_ar":"اكتب عن مشاعرك.","items":[{"q":"When do you feel excited? Write: I feel excited when ___.","answer":"I feel excited when we go to the beach.","explanation":"A true sentence.","explanation_ar":"جملة صحيحة.","dok":2,"skill":"personal writing","stage":"production"},{"q":"When do you feel tired?","answer":"I feel tired after football.","explanation":"A true sentence.","explanation_ar":"جملة صحيحة.","dok":1,"skill":"personal writing","stage":"production"},{"q":"Write a sentence with a synonym: glad, afraid or mad.","answer":"I am glad you are my friend.","explanation":"Use one synonym correctly.","explanation_ar":"استخدم مرادفًا بشكل صحيح.","dok":2,"skill":"synonyms","stage":"production"},{"q":"What does a good friend do? Use two words from the lesson.","answer":"A good friend shares and cares.","explanation":"Two lesson words.","explanation_ar":"كلمتان من الدرس.","dok":2,"skill":"vocabulary use","stage":"production"}]}],"game":{"name":"Feelings Charades","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Face match: a cartoon face appears; the child taps the feeling word, then a second tap on its synonym for a bonus star. 12 faces, 10 seconds each.","Two teams. A player takes a card and acts the feeling with face and body only.","The team has 20 seconds to guess the feeling.","Correct feeling = 1 point; a correct synonym too = 1 bonus point.","Teams take turns until the cards are finished.","The team with more points wins; everyone shows the 'kind' face at the end."],"data":[]},"exit_quiz":[{"q":"Which word is a feeling?","answer":"excited","explanation":"Excited is a feeling.","explanation_ar":"excited شعور.","options":["game","together","share","excited"],"dok":1,"skill":"vocabulary"},{"q":"Which word means *afraid*?","answer":"scared","explanation":"Scared = afraid.","explanation_ar":"scared = afraid.","options":["kind","glad","tired","scared"],"dok":1,"skill":"synonyms"},{"q":"Which word means *glad*?","answer":"happy","explanation":"Glad = happy.","explanation_ar":"glad = happy.","options":["happy","mad","sleepy","unhappy"],"dok":1,"skill":"synonyms"},{"q":"You make happy sounds at a funny joke. You ___.","answer":"laugh","explanation":"Laugh = happy sounds.","explanation_ar":"تضحك.","options":["cry","hide","laugh","share"],"dok":1,"skill":"vocabulary"},{"q":"Which sentence uses a feeling word correctly?","answer":"I feel tired after school.","explanation":"I feel + feeling word.","explanation_ar":"I feel + شعور.","options":["I feel tired after school.","I am feel tired.","I tired feel.","I feeling tired."],"dok":2,"skill":"usage"},{"q":"*Majed gives half of his sandwich to Ali.* What does Majed do?","answer":"He shares.","explanation":"Giving part = sharing.","explanation_ar":"يتشارك.","options":["He shares.","He laughs.","He hides.","He sleeps."],"dok":2,"skill":"vocabulary in context"},{"q":"Which pair are synonyms?","answer":"angry – mad","explanation":"Angry and mad mean the same.","explanation_ar":"angry وmad مترادفتان.","options":["happy – sad","angry – mad","tired – excited","kind – angry"],"dok":1,"skill":"synonyms"},{"q":"Which sentence about Eid is correct?","answer":"I am excited about Eid.","explanation":"excited = how I feel.","explanation_ar":"excited.","options":["I am exciting about Eid.","I excited about Eid.","I am excited about Eid.","I am excite about Eid."],"dok":2,"skill":"usage"},{"q":"*Huda listens and says, \"I know how you feel.\"* Huda ___ her friend.","answer":"understands","explanation":"Knowing how someone feels = understanding.","explanation_ar":"تفهم صديقتها.","options":["forgets","understands","hides","shouts at"],"dok":2,"skill":"vocabulary in context"},{"q":"Why is it good to know synonyms?","answer":"They help us understand words and make writing more interesting.","explanation":"Synonyms add variety and help meaning.","explanation_ar":"تساعد على الفهم وتجعل الكتابة أجمل.","options":["They make words longer.","They are always opposites.","They are only for poems.","They help us understand words and make writing more interesting."],"dok":3,"skill":"strategy"}],"images":[{"id":"IMG-RW-L02-U1-LS1-V01","prompt":"Picture for the word 'kind': a boy helping a classmate pick up dropped books"},{"id":"IMG-RW-L02-U1-LS1-V02","prompt":"Picture for the word 'share': two children sharing a box of dates"},{"id":"IMG-RW-L02-U1-LS1-V03","prompt":"Picture for the word 'smile': a girl smiling widely"},{"id":"IMG-RW-L02-U1-LS1-V04","prompt":"Picture for the word 'sad': a girl with a tear sitting on a bench"},{"id":"IMG-RW-L02-U1-LS1-V05","prompt":"Picture for the word 'angry': a boy with a red face and crossed arms"},{"id":"IMG-RW-L02-U1-LS1-V06","prompt":"Picture for the word 'scared': a kitten hiding behind a box"},{"id":"IMG-RW-L02-U1-LS1-V07","prompt":"Picture for the word 'excited': a boy jumping with joy next to a packed bag"},{"id":"IMG-RW-L02-U1-LS1-V08","prompt":"Picture for the word 'tired': a boy yawning on a sofa"},{"id":"IMG-RW-L02-U1-LS1-V09","prompt":"Picture for the word 'together': two friends building a sandcastle"},{"id":"IMG-RW-L02-U1-LS1-V10","prompt":"Picture for the word 'sorry': a boy giving back a pencil with a sorry face"},{"id":"IMG-RW-L02-U1-LS1-V11","prompt":"Picture for the word 'thank': a girl saying thank you to a teacher holding a book"},{"id":"IMG-RW-L02-U1-LS1-V12","prompt":"Picture for the word 'game': children playing a board game"},{"id":"IMG-RW-L02-U1-LS1-V13","prompt":"Picture for the word 'laugh': three friends laughing together"},{"id":"IMG-RW-L02-U1-LS1-V14","prompt":"Picture for the word 'care': a boy giving water to a tired friend"},{"id":"IMG-RW-L02-U1-LS1-V15","prompt":"Picture for the word 'feeling': a row of four faces: happy, sad, angry, scared"},{"id":"IMG-RW-L02-U1-LS1-V16","prompt":"Picture for the word 'understand': a girl listening carefully to a sad friend"},{"id":"IMG-RW-L02-U1-LS1-01","prompt":"Friends play and share in a park, and Noura goes to help a sad child."},{"id":"IMG-RW-L02-U1-LS1-02","prompt":"Six faces showing different feelings."},{"id":"IMG-RW-L02-U1-LS1-03","prompt":"Puzzle cards clicking together in matching pairs."}],"audio":[{"id":"AUD-RW-L02-U1-LS1-V01","script":"kind. It is kind to help a new student."},{"id":"AUD-RW-L02-U1-LS1-V02","script":"share. Badr shares his dates with me."},{"id":"AUD-RW-L02-U1-LS1-V03","script":"smile. Smile at your new friend."},{"id":"AUD-RW-L02-U1-LS1-V04","script":"sad. Reem is sad because her cat is sick."},{"id":"AUD-RW-L02-U1-LS1-V05","script":"angry. Faris is angry because his tower fell."},{"id":"AUD-RW-L02-U1-LS1-V06","script":"scared. The kitten is scared of the dog."},{"id":"AUD-RW-L02-U1-LS1-V07","script":"excited. I am excited about the trip."},{"id":"AUD-RW-L02-U1-LS1-V08","script":"tired. After football, I am tired."},{"id":"AUD-RW-L02-U1-LS1-V09","script":"together. We build a sandcastle together."},{"id":"AUD-RW-L02-U1-LS1-V10","script":"sorry. I am sorry I broke your pencil."},{"id":"AUD-RW-L02-U1-LS1-V11","script":"thank. Thank your teacher for the book."},{"id":"AUD-RW-L02-U1-LS1-V12","script":"game. Let's play a game!"},{"id":"AUD-RW-L02-U1-LS1-V13","script":"laugh. We laugh at the funny story."},{"id":"AUD-RW-L02-U1-LS1-V14","script":"care. Good friends care about each other."},{"id":"AUD-RW-L02-U1-LS1-V15","script":"feeling. Excited is a happy feeling."},{"id":"AUD-RW-L02-U1-LS1-V16","script":"understand. I understand how you feel."},{"id":"AUD-RW-L02-U1-LS1-VID","script":"How do you feel today? Happy? Sad? Let's learn feeling words! Happy… sad… angry… scared. Look at the faces! Excited – jumping and clapping! Tired – yawning and sleepy. Synonyms are words with the same meaning. Happy… glad! Scared… afraid! Angry… mad! Good friends share, smile, laugh and care. They say sorry and thank you. Every feeling is OK. Now tell a friend: How do you feel?"}]},{"id":"RW-L02-U1-LS2","title":"The Broken Kite","lesson_type":"close_reading","objectives":["read a story of about 135 words and answer questions about characters, events and feelings","ask questions before, during and after reading","explain the lesson of the story with evidence"],"objectives_ar":["قراءة قصة من نحو 135 كلمة والإجابة عن أسئلة حول الشخصيات والأحداث والمشاعر.","طرح الأسئلة قبل القراءة وأثناءها وبعدها.","شرح الدرس المستفاد من القصة مع الدليل."],"success_criteria":["I can ask a question before, during and after reading.","I can answer questions with words from the story.","I can say what the story teaches."],"success_criteria_ar":["أستطيع طرح سؤال قبل القراءة وأثناءها وبعدها.","أستطيع الإجابة عن الأسئلة بكلمات من القصة.","أستطيع قول ما تعلّمه القصة."],"map_area":"Literary Text: Key Ideas and Details","vocabulary":[{"word":"kite","pos":"noun","ipa":"/kaɪt/","definition":"a toy that flies in the wind on a string","arabic":"طائرة ورقية","example":"My kite is blue and yellow.","image_id":"IMG-RW-L02-U1-LS2-V01","audio_id":"AUD-RW-L02-U1-LS2-V01","tier":"core"},{"word":"string","pos":"noun","ipa":"/strɪŋ/","definition":"a long thin line","arabic":"خيط","example":"Hold the string tightly.","image_id":"IMG-RW-L02-U1-LS2-V02","audio_id":"AUD-RW-L02-U1-LS2-V02","tier":"core"},{"word":"suddenly","pos":"adverb","ipa":"/ˈsʌdənli/","definition":"very quickly, when you do not expect it","arabic":"فجأة","example":"Suddenly, the lights went out.","image_id":"IMG-RW-L02-U1-LS2-V03","audio_id":"AUD-RW-L02-U1-LS2-V03","tier":"core"},{"word":"broken","pos":"adjective","ipa":"/ˈbroʊkən/","definition":"in pieces; not working","arabic":"مكسور","example":"The toy car is broken.","image_id":"IMG-RW-L02-U1-LS2-V04","audio_id":"AUD-RW-L02-U1-LS2-V04","tier":"core"},{"word":"tears","pos":"noun","ipa":"/tɪrz/","definition":"drops of water from your eyes when you cry","arabic":"دموع","example":"Her tears fall on the page.","image_id":"IMG-RW-L02-U1-LS2-V05","audio_id":"AUD-RW-L02-U1-LS2-V05","tier":"core"},{"word":"fix","pos":"verb","ipa":"/fɪks/","definition":"to make something work again","arabic":"يصلح","example":"Dad can fix my bike.","image_id":"IMG-RW-L02-U1-LS2-V06","audio_id":"AUD-RW-L02-U1-LS2-V06","tier":"core"},{"word":"forgive","pos":"verb","ipa":"/fərˈɡɪv/","definition":"to stop being angry with someone","arabic":"يسامح","example":"Please forgive me.","image_id":"IMG-RW-L02-U1-LS2-V07","audio_id":"AUD-RW-L02-U1-LS2-V07","tier":"core"}],"explanation":{"text":"Good readers **ask questions** all the time. Questions help you think and understand.\n\n**Before** reading: look at the title and picture. Ask: *What will happen?* (*Why is the kite broken?*)\n\n**During** reading: stop and ask: *Why did that happen? How does the character feel?*\n\n**After** reading: ask: *What did I learn? What would I do?* Then find the answers in the story.","examples":["Before: *The Broken Kite* → **How does the kite break?**","Before: picture of two sad boys → **Are they friends? Why are they sad?**","During: *Suddenly, the wind pushes the kite into a tree.* → **Will Omar be angry?**","During: *Sami's eyes are full of tears.* → **How does Sami feel?** → sad and scared.","During: *Omar takes a deep breath.* → **Why does he do that?** → to calm down.","After: **Who broke the kite?** → the wind, not Sami.","After: **What do the friends do the next day?** → they fix the kite together.","After: **What does the story teach?** → Good friends share and forgive.","After (Me): **What would I do if my friend broke my toy?**"],"common_errors":["✗ Why the kite is broken? → ✓ Why is the kite broken? (In questions, put **is** before the subject.)","✗ How Sami feels? → ✓ How does Sami feel? (Use **does** in this question.)","✗ Omar forgive Sami. → ✓ Omar forgives Sami. (One person → **forgives**.)","✗ The kite is break. → ✓ The kite is broken. (After **is**, use **broken**.)","✗ Sami say sorry. → ✓ Sami says sorry. (One person → **says**.)","✗ Suddenly the wind pushes the kite. (no comma) → ✓ Suddenly, the wind pushes the kite. (Put a comma after *Suddenly*.)"],"arabic":"القارئ الجيد يطرح الأسئلة دائمًا؛ فالأسئلة تساعده على التفكير والفهم.\n\nقبل القراءة: انظر إلى العنوان والصورة واسأل: ماذا سيحدث؟\n\nأثناء القراءة: توقف واسأل: لماذا حدث ذلك؟ بماذا تشعر الشخصية؟\n\nبعد القراءة: اسأل: ماذا تعلمت؟ ماذا كنت سأفعل؟ ثم ابحث عن الإجابات في القصة.\n\nانتبه: نقول Why is the kite broken? ولا نقول Why the kite is broken?"},"video":{"script":[{"time":"00:00–00:20","narration":"Look at the title: The Broken Kite. What question can you ask before reading?","on_screen":"BEFORE: Ask a question ❓","visual":"A torn red kite in a tree; a big question mark floats beside it."},{"time":"00:20–01:30","narration":"Omar has a new red kite. He takes it to the park with Sami…","on_screen":"(story text, part by part)","visual":"The story is animated: the kite flies high, Sami holds the string, the wind pushes it into a tree – Crack!"},{"time":"01:30–01:55","narration":"Stop! During reading, ask: How does Sami feel? Sad and scared. Will Omar be angry?","on_screen":"DURING: Stop and ask ✋","visual":"The video pauses; a thought bubble with two faces (sad, scared) appears above Sami."},{"time":"01:55–02:25","narration":"Omar takes a deep breath. \"It is OK. It was the wind, not you.\"","on_screen":"A deep breath 😮‍💨","visual":"Omar breathes in and out slowly; his red face becomes calm."},{"time":"02:25–03:00","narration":"After reading, ask: What does the story teach? Good friends share, and good friends forgive!","on_screen":"AFTER: What did I learn? 💡","visual":"The two boys fly the fixed kite; the words 'share' and 'forgive' float up with the kite."}],"captions_ar":["انظروا إلى العنوان: الطائرة الورقية المكسورة. ما السؤال الذي يمكن أن تطرحه قبل القراءة؟","لدى عمر طائرة ورقية حمراء جديدة. يأخذها إلى الحديقة مع سامي…","توقف! أثناء القراءة اسأل: بماذا يشعر سامي؟ بالحزن والخوف. هل سيغضب عمر؟","يأخذ عمر نفسًا عميقًا ويقول: لا بأس، إنها الرياح وليست أنت.","بعد القراءة اسأل: ماذا تعلّمنا القصة؟ الأصدقاء الجيدون يتشاركون ويسامحون!"],"voice":"Narrator: American English, warm female teacher, speed 0.85. Omar: energetic boy; Sami: softer, gentle boy (shaky voice when sorry). Wind sound effects lightly."},"texts":[{"type":"reading","title":"The Broken Kite","body":"Omar has a new red kite. He takes it to the park with Sami. The wind is strong, and the kite flies high. Omar is excited!\n\nThen Sami asks, \"Can I fly it too?\" Omar gives him the string. Suddenly, the wind pushes the kite into a tree. Crack! The kite is broken.\n\nSami feels sad and scared. \"I am sorry, Omar,\" he says quietly.\n\nOmar is angry for a moment. Then he looks at Sami's face. Sami's eyes are full of tears. Omar takes a deep breath. \"It is OK,\" he says. \"It was the wind, not you.\"\n\nThe next day, the two friends fix the kite together with tape and paper. It is not perfect, but it can fly. Omar and Sami laugh and run. Good friends share, and good friends forgive.","word_count":134,"audio_id":"AUD-RW-L02-U1-LS2-T1","id":"TXT-RW-L02-U1-LS2-1","genre":"narrative","role":"main","difficulty":"200L–350L","glossary":[{"word":"string","definition":"the long thin line you hold to fly a kite","arabic":"خيط"},{"word":"forgive","definition":"to stop being angry with someone","arabic":"يسامح"},{"word":"perfect","definition":"with no problems at all","arabic":"مثالي / كامل"}]}],"activities":[{"id":"RW-L02-U1-LS2-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read the story. Choose the answer.","instructions_ar":"اقرأ القصة واختر الإجابة.","items":[{"q":"What color is Omar's new kite?","answer":"red","explanation":"Text: a new red kite.","explanation_ar":"أحمر.","options":["blue","green","yellow","red"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Where do the boys fly the kite?","answer":"in the park","explanation":"Text: to the park.","explanation_ar":"في الحديقة العامة.","options":["at school","on the beach","in the park","on the roof"],"dok":1,"skill":"key details: where","stage":"controlled"},{"q":"Who holds the string when the kite breaks?","answer":"Sami","explanation":"Omar gives him the string.","explanation_ar":"سامي.","options":["Sami","Omar","Omar's father","Noura"],"dok":1,"skill":"key details: who","stage":"controlled"},{"q":"What pushes the kite into a tree?","answer":"the wind","explanation":"Text: the wind pushes the kite.","explanation_ar":"الرياح.","options":["Sami","the wind","a bird","Omar"],"dok":1,"skill":"cause and effect","stage":"controlled"},{"q":"What does Sami say?","answer":"\"I am sorry, Omar.\"","explanation":"Sami says sorry quietly.","explanation_ar":"يقول آسف.","options":["\"It is OK.\"","\"Let's go home.\"","\"I am sorry, Omar.\"","\"Look at me!\""],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What do they use to fix the kite?","answer":"tape and paper","explanation":"Text: with tape and paper.","explanation_ar":"شريط لاصق وورق.","options":["glue and wood","tape and paper","string and stones","a new kite"],"dok":1,"skill":"key details","stage":"controlled"}]},{"id":"RW-L02-U1-LS2-A2","type":"true_false","stage":"guided","instructions":"Guided practice: True or false?","instructions_ar":"صح أم خطأ؟","items":[{"q":"Omar is excited when the kite flies high.","answer":"true","explanation":"Text: Omar is excited!","explanation_ar":"صحيح.","options":["true","false"],"dok":1,"skill":"feelings","stage":"guided"},{"q":"Sami breaks the kite on purpose.","answer":"false","explanation":"It was the wind, not Sami.","explanation_ar":"الرياح هي السبب.","options":["true","false"],"dok":2,"skill":"cause and effect","stage":"guided"},{"q":"Omar is angry for a long time.","answer":"false","explanation":"Only for a moment.","explanation_ar":"لمدة قصيرة فقط.","options":["true","false"],"dok":2,"skill":"key details","stage":"guided"},{"q":"Sami's eyes are full of tears.","answer":"true","explanation":"Text says so.","explanation_ar":"صحيح.","options":["true","false"],"dok":1,"skill":"key details","stage":"guided"},{"q":"The fixed kite is perfect.","answer":"false","explanation":"It is not perfect, but it can fly.","explanation_ar":"ليست مثالية.","options":["true","false"],"dok":1,"skill":"key details","stage":"guided"},{"q":"The friends fix the kite the next day.","answer":"true","explanation":"Text: The next day…","explanation_ar":"صحيح.","options":["true","false"],"dok":1,"skill":"sequence","stage":"guided"}]},{"id":"RW-L02-U1-LS2-A3","type":"highlight","stage":"freer","instructions":"Find the evidence: Before, during, after: underline or choose.","instructions_ar":"قبل وأثناء وبعد: ضع خطًا أو اختر.","items":[{"q":"Underline what Omar does to calm down.","answer":"Omar takes a deep breath.","explanation":"A deep breath helps him calm down.","explanation_ar":"النفس العميق يهدئه.","evidence":"Omar takes a deep breath.","text_id":"TXT-RW-L02-U1-LS2-1","dok":2,"skill":"evidence","stage":"freer","sentences":["Omar has a new red kite.","He takes it to the park with Sami.","The wind is strong, and the kite flies high.","Omar is excited!","Then Sami asks, \"Can I fly it too?\"","Omar gives him the string.","Suddenly, the wind pushes the kite into a tree.","Crack!","The kite is broken.","Sami feels sad and scared.","\"I am sorry, Omar,\" he says quietly.","Omar is angry for a moment.","Then he looks at Sami's face.","Sami's eyes are full of tears.","Omar takes a deep breath.","\"It is OK,\" he says.","\"It was the wind, not you.\"","The next day, the two friends fix the kite together with tape and paper.","It is not perfect, but it can fly.","Omar and Sami laugh and run.","Good friends share, and good friends forgive."]},{"q":"Underline the sentence that tells the lesson of the story.","answer":"Good friends share, and good friends forgive.","explanation":"This is the message.","explanation_ar":"هذه رسالة القصة.","evidence":"Good friends share, and good friends forgive.","text_id":"TXT-RW-L02-U1-LS2-1","dok":2,"skill":"theme","stage":"freer","sentences":["Omar has a new red kite.","He takes it to the park with Sami.","The wind is strong, and the kite flies high.","Omar is excited!","Then Sami asks, \"Can I fly it too?\"","Omar gives him the string.","Suddenly, the wind pushes the kite into a tree.","Crack!","The kite is broken.","Sami feels sad and scared.","\"I am sorry, Omar,\" he says quietly.","Omar is angry for a moment.","Then he looks at Sami's face.","Sami's eyes are full of tears.","Omar takes a deep breath.","\"It is OK,\" he says.","\"It was the wind, not you.\"","The next day, the two friends fix the kite together with tape and paper.","It is not perfect, but it can fly.","Omar and Sami laugh and run.","Good friends share, and good friends forgive."]},{"q":"Which is a good question to ask BEFORE reading?","answer":"How does the kite break?","explanation":"Before reading, we guess from the title.","explanation_ar":"قبل القراءة نتساءل من العنوان.","options":["What do they use to fix it?","What did I learn?","Who says sorry?","How does the kite break?"],"dok":2,"skill":"asking questions","stage":"freer"},{"q":"Why does Omar change from angry to kind?","answer":"He sees Sami is sad and knows it was the wind.","explanation":"He looks at Sami's face and understands.","explanation_ar":"رأى حزن سامي وفهم.","options":["He sees Sami is sad and knows it was the wind.","Sami buys him a new kite.","His father tells him to.","He forgets about the kite."],"dok":3,"skill":"character change","stage":"freer"}]},{"id":"RW-L02-U1-LS2-A4","type":"open","stage":"production","instructions":"Writing: After-reading questions. Write your answers.","instructions_ar":"أسئلة ما بعد القراءة: اكتب إجاباتك.","items":[{"q":"Write one question you asked DURING reading. Then answer it.","answer":"Will Omar be angry? Yes, for a moment, but then he forgives Sami.","explanation":"A question + answer.","explanation_ar":"سؤال + إجابة.","dok":2,"skill":"asking questions","stage":"production"},{"q":"Is Omar a good friend? Why?","answer":"Yes, because he forgives Sami and helps fix the kite.","explanation":"Yes/No + because + evidence.","explanation_ar":"نعم/لا + because + دليل.","dok":3,"skill":"evaluate","stage":"production"},{"q":"What would YOU do if a friend broke your toy by mistake?","answer":"I would say, 'It is OK,' and we would fix it together.","explanation":"A kind action.","explanation_ar":"تصرف لطيف.","dok":3,"skill":"connect","stage":"production"},{"q":"Write the lesson of the story in your own words.","answer":"Friends forgive each other.","explanation":"A short lesson.","explanation_ar":"درس قصير.","dok":2,"skill":"theme","stage":"production"}]},{"id":"RW-L02-U1-LS2-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"The Broken Kite\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “The Broken Kite”.","answer":"134 words","title":"The Broken Kite","body":"Omar has a new red kite. He takes it to the park with Sami. The wind is strong, and the kite flies high. Omar is excited!\n\nThen Sami asks, \"Can I fly it too?\" Omar gives him the string. Suddenly, the wind pushes the kite into a tree. Crack! The kite is broken.\n\nSami feels sad and scared. \"I am sorry, Omar,\" he says quietly.\n\nOmar is angry for a moment. Then he looks at Sami's face. Sami's eyes are full of tears. Omar takes a deep breath. \"It is OK,\" he says. \"It was the wind, not you.\"\n\nThe next day, the two friends fix the kite together with tape and paper. It is not perfect, but it can fly. Omar and Sami laugh and run. Good friends share, and good friends forgive.","words":134,"limit":161}],"time_limit_sec":161}],"game":{"name":"Question Ball","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Question builder: the app shows a story picture and a color (before/during/after); the child builds a question from word tiles (Why / How / Who + is/does…) and then taps the answer in the text.","Students stand in a circle; the teacher throws the ball.","The catcher looks at the color under their right thumb and asks a question of that type.","They throw the ball to a friend, who answers.","A good question = 1 point; a correct answer = 1 point.","Play for 6 minutes."],"data":[]},"exit_quiz":[{"q":"Who owns the kite?","answer":"Omar","explanation":"Omar has a new red kite.","explanation_ar":"الطائرة لعمر.","options":["Sami","Adam","Faris","Omar"],"dok":1,"skill":"key details"},{"q":"How does Omar feel when the kite flies high?","answer":"excited","explanation":"Text: Omar is excited!","explanation_ar":"متحمس.","options":["sad","scared","excited","tired"],"dok":1,"skill":"feelings"},{"q":"What sound does the kite make in the tree?","answer":"Crack!","explanation":"Text: Crack!","explanation_ar":"Crack!","options":["Crack!","Pop!","Splash!","Boom!"],"dok":1,"skill":"key details"},{"q":"How does Sami feel after the kite breaks?","answer":"sad and scared","explanation":"Text: Sami feels sad and scared.","explanation_ar":"حزين وخائف.","options":["happy and excited","sad and scared","angry and mad","tired and sleepy"],"dok":1,"skill":"feelings"},{"q":"*Suddenly, the wind pushes the kite.* *Suddenly* means ___.","answer":"very quickly, when you don't expect it","explanation":"Suddenly = quickly and not expected.","explanation_ar":"فجأة.","options":["very slowly","very quickly, when you don't expect it","every day","after a long time"],"dok":2,"skill":"word in context"},{"q":"Which question is best to ask DURING reading?","answer":"How does Sami feel now?","explanation":"During reading we ask about what is happening.","explanation_ar":"أثناء القراءة نسأل عما يحدث.","options":["How does Sami feel now?","What is the title?","What will the cover show?","What did the whole story teach?"],"dok":2,"skill":"asking questions"},{"q":"Why does Omar say *It was the wind, not you*?","answer":"He knows Sami did not break it on purpose.","explanation":"The wind broke it.","explanation_ar":"يعرف أن سامي لم يقصد.","options":["He is still very angry.","He wants a new kite.","He knows Sami did not break it on purpose.","He wants Sami to go home."],"dok":2,"skill":"inference"},{"q":"What do the friends do the next day?","answer":"They fix the kite together.","explanation":"Text: fix the kite together.","explanation_ar":"يصلحانها معًا.","options":["They buy a new kite.","They stop being friends.","They fix the kite together.","They stay at home."],"dok":1,"skill":"sequence"},{"q":"What does *forgive* mean in the story?","answer":"stop being angry with someone","explanation":"Forgive = stop being angry.","explanation_ar":"يسامح.","options":["break something","stop being angry with someone","fly a kite","run fast"],"dok":2,"skill":"word in context"},{"q":"Which is the BEST lesson of the story?","answer":"Good friends share and forgive.","explanation":"The last sentence tells the lesson.","explanation_ar":"الأصدقاء يتشاركون ويسامحون.","options":["Kites are always red.","Never go to the park.","Wind is fun.","Good friends share and forgive."],"dok":3,"skill":"theme"}],"images":[{"id":"IMG-RW-L02-U1-LS2-V01","prompt":"Picture for the word 'kite': a colorful kite high in the sky"},{"id":"IMG-RW-L02-U1-LS2-V02","prompt":"Picture for the word 'string': a hand holding a kite string"},{"id":"IMG-RW-L02-U1-LS2-V03","prompt":"Picture for the word 'suddenly': a surprised child as a balloon pops"},{"id":"IMG-RW-L02-U1-LS2-V04","prompt":"Picture for the word 'broken': a toy car with a wheel off"},{"id":"IMG-RW-L02-U1-LS2-V05","prompt":"Picture for the word 'tears': a child's face with two tears"},{"id":"IMG-RW-L02-U1-LS2-V06","prompt":"Picture for the word 'fix': a father fixing a bicycle wheel"},{"id":"IMG-RW-L02-U1-LS2-V07","prompt":"Picture for the word 'forgive': two friends shaking hands and smiling"},{"id":"IMG-RW-L02-U1-LS2-01","prompt":"A red kite is stuck in a tree while Sami and Omar look up."},{"id":"IMG-RW-L02-U1-LS2-02","prompt":"Omar calmly comforts Sami, who is crying."},{"id":"IMG-RW-L02-U1-LS2-03","prompt":"The boys fix the kite and then fly it together."}],"audio":[{"id":"AUD-RW-L02-U1-LS2-V01","script":"kite. My kite is blue and yellow."},{"id":"AUD-RW-L02-U1-LS2-V02","script":"string. Hold the string tightly."},{"id":"AUD-RW-L02-U1-LS2-V03","script":"suddenly. Suddenly, the lights went out."},{"id":"AUD-RW-L02-U1-LS2-V04","script":"broken. The toy car is broken."},{"id":"AUD-RW-L02-U1-LS2-V05","script":"tears. Her tears fall on the page."},{"id":"AUD-RW-L02-U1-LS2-V06","script":"fix. Dad can fix my bike."},{"id":"AUD-RW-L02-U1-LS2-V07","script":"forgive. Please forgive me."},{"id":"AUD-RW-L02-U1-LS2-T1","script":"Omar has a new red kite. He takes it to the park with Sami. The wind is strong, and the kite flies high. Omar is excited! Then Sami asks, \"Can I fly it too?\" Omar gives him the string. Suddenly, the wind pushes the kite into a tree. Crack! The kite is broken. Sami feels sad and scared. \"I am sorry, Omar,\" he says quietly. Omar is angry for a moment. Then he looks at Sami's face. Sami's eyes are full of tears. Omar takes a deep breath. \"It is OK,\" he says. \"It was the wind, not you.\" The next day, the two friends fix the kite together with tape and paper. It is not perfect, but it can fly. Omar and Sami laugh and run. Good friends share, and good friends forgive."},{"id":"AUD-RW-L02-U1-LS2-VID","script":"Look at the title: The Broken Kite. What question can you ask before reading? Omar has a new red kite. He takes it to the park with Sami… Stop! During reading, ask: How does Sami feel? Sad and scared. Will Omar be angry? Omar takes a deep breath. \"It is OK. It was the wind, not you.\" After reading, ask: What does the story teach? Good friends share, and good friends forgive!"}]},{"id":"RW-L02-U1-LS3","title":"Character feelings and actions: \"When I Feel…\"","lesson_type":"strategy_paired_text","objectives":["describe how characters feel and what they do because of their feelings","use actions and words as clues to a character's feelings","connect feelings and actions in a story and a poem"],"objectives_ar":["وصف مشاعر الشخصيات وما تفعله بسببها.","استخدام الأفعال والأقوال دليلًا على مشاعر الشخصية.","ربط المشاعر بالأفعال في قصة وقصيدة."],"success_criteria":["I can say how a character feels.","I can find an action that shows the feeling.","I can match feelings and actions in the poem."],"success_criteria_ar":["أستطيع قول بماذا تشعر الشخصية.","أستطيع إيجاد فعل يدل على الشعور.","أستطيع مطابقة المشاعر والأفعال في القصيدة."],"map_area":"Literary Text: Key Ideas and Details","vocabulary":[{"word":"count","pos":"verb","ipa":"/kaʊnt/","definition":"to say numbers in order","arabic":"يعدّ","example":"Count to ten slowly.","image_id":"IMG-RW-L02-U1-LS3-V01","audio_id":"AUD-RW-L02-U1-LS3-V01","tier":"core"},{"word":"breath","pos":"noun","ipa":"/brɛθ/","definition":"the air you take into your body","arabic":"نَفَس","example":"Take a deep breath.","image_id":"IMG-RW-L02-U1-LS3-V02","audio_id":"AUD-RW-L02-U1-LS3-V02","tier":"core"},{"word":"brave","pos":"adjective","ipa":"/breɪv/","definition":"not afraid to do something hard","arabic":"شجاع","example":"Badr is brave at the dentist.","image_id":"IMG-RW-L02-U1-LS3-V03","audio_id":"AUD-RW-L02-U1-LS3-V03","tier":"core"},{"word":"rest","pos":"verb","ipa":"/rɛst/","definition":"to stop and relax","arabic":"يستريح","example":"Rest after you run.","image_id":"IMG-RW-L02-U1-LS3-V04","audio_id":"AUD-RW-L02-U1-LS3-V04","tier":"core"},{"word":"cheeks","pos":"noun","ipa":"/tʃiks/","definition":"the soft sides of your face","arabic":"الخدّان","example":"Her cheeks are pink.","image_id":"IMG-RW-L02-U1-LS3-V05","audio_id":"AUD-RW-L02-U1-LS3-V05","tier":"core"},{"word":"action","pos":"noun","ipa":"/ˈækʃən/","definition":"something a person does","arabic":"فعل / تصرّف","example":"Laughing is a happy action.","image_id":"IMG-RW-L02-U1-LS3-V06","audio_id":"AUD-RW-L02-U1-LS3-V06","tier":"core"},{"word":"OK","pos":"adjective","ipa":"/ˌoʊˈkeɪ/","definition":"all right; fine","arabic":"لا بأس / حسنًا","example":"Is everything OK?","image_id":"IMG-RW-L02-U1-LS3-V07","audio_id":"AUD-RW-L02-U1-LS3-V07","tier":"core"}],"explanation":{"text":"Characters have **feelings**. Their **actions** (what they do) and **words** (what they say) show us how they feel.\n\nAsk: **How does the character feel?** Then ask: **What does the character do or say that shows it?**\n\nFeelings can **change** in a story. Omar is excited, then angry, then kind and happy.\n\nUse a **Feelings Map**: feeling → action or words → clue from the text.","examples":["Omar feels **excited** → the kite flies high and he runs. Clue: *Omar is excited!*","Sami feels **sorry** → he says, *\"I am sorry, Omar.\"*","Sami feels **sad** → *his eyes are full of tears*.","Omar feels **angry** → then he *takes a deep breath* to calm down.","Omar feels **kind** → he says, *\"It is OK.\"*","Poem – **happy** → *I laugh and play.*","Poem – **angry** → *I count to ten.*","Poem – **scared** → *I tell my dad.*","Poem – **excited** → *my cheeks go red!*"],"common_errors":["✗ Sami is sad because tears. → ✓ Sami is sad. His eyes are full of tears. (Use a full sentence for the clue.)","✗ When I feel angry, I am count to ten. → ✓ When I feel angry, I count to ten. (No **am** before the action word.)","✗ He feels angry, so he hits. → ✓ He feels angry, so he takes a breath. (Good actions help angry feelings.)","✗ When I feel sad I need friend. → ✓ When I feel sad, I need a friend. (Comma after the *when* part; use **a friend**.)","✗ Omar feel kind. → ✓ Omar feels kind. (One person → **feels**.)","✗ I am brave of the dark. → ✓ I am brave in the dark. / I am not afraid of the dark. (Say **afraid of**, but **brave in/at**.)"],"arabic":"للشخصيات مشاعر، وأفعالها وأقوالها تدلنا على ما تشعر به.\n\nاسأل: بماذا تشعر الشخصية؟ ثم اسأل: ماذا تفعل أو تقول ليدل على ذلك؟\n\nقد تتغير المشاعر في القصة: عمر كان متحمسًا، ثم غاضبًا، ثم لطيفًا وسعيدًا.\n\nاستخدم خريطة المشاعر: الشعور ← الفعل أو القول ← الدليل من النص."},"video":{"script":[{"time":"00:00–00:15","narration":"Feelings and actions go together. What do YOU do when you feel happy?","on_screen":"Feelings → Actions","visual":"A heart icon connects with an arrow to a running child."},{"time":"00:15–01:05","narration":"When I feel happy, I laugh and play…","on_screen":"(the poem)","visual":"Layla reads; for each couplet a child acts it: laughing, getting help, counting to ten, telling Dad, resting, red cheeks."},{"time":"01:05–01:35","narration":"Look: angry → count to ten. Scared → tell my dad. The action shows the feeling!","on_screen":"angry → count to ten · scared → tell Dad","visual":"Two feeling faces connect to action pictures with arrows."},{"time":"01:35–02:10","narration":"In The Broken Kite, Omar feels excited, then angry, then kind. His feelings change!","on_screen":"excited → angry → kind","visual":"Omar's face changes along a line, with matching story moments."},{"time":"02:10–02:40","narration":"Every feeling is OK. What we DO with our feelings is important.","on_screen":"Every feeling is OK 💛","visual":"Children in a circle; Saqr nods kindly."}],"captions_ar":["المشاعر والأفعال تسيران معًا. ماذا تفعل أنت عندما تشعر بالسعادة؟","عندما أشعر بالسعادة أضحك وألعب…","انظروا: الغضب ← العدّ إلى عشرة. الخوف ← أخبر أبي. الفعل يدل على الشعور!","في قصة الطائرة المكسورة يشعر عمر بالحماس، ثم الغضب، ثم اللطف. مشاعره تتغير!","كل المشاعر مقبولة، والمهم هو ما نفعله بها."],"voice":"Narrator: American English, warm female teacher, speed 0.85. The poem is read by Layla in a calm, rhythmic voice; each feeling line has matching expression."},"texts":[{"type":"reading","title":"When I Feel…","body":"When I feel happy, I laugh and play.\n\nI share my toys with friends all day.\n\nWhen I feel sad, I need a friend,\n\na kind word and a hand to lend.\n\nWhen I feel angry, I count to ten.\n\nI take a breath, then talk again.\n\nWhen I feel scared, I tell my dad,\n\nand soon I am not scared or sad.\n\nWhen I feel tired, I rest my head.\n\nWhen I'm excited, my cheeks go red!\n\nEvery feeling is OK, you see.\n\nAll my feelings are part of me!","word_count":91,"audio_id":"AUD-RW-L02-U1-LS3-T1","id":"TXT-RW-L02-U1-LS3-1","genre":"poetry (original)","role":"paired","difficulty":"200L–350L","glossary":[{"word":"a hand to lend","definition":"help","arabic":"يد المساعدة"},{"word":"cheeks","definition":"the soft sides of your face","arabic":"الخدّان"}]}],"activities":[{"id":"RW-L02-U1-LS3-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read the poem. Match the feeling and the action.","instructions_ar":"اقرأ القصيدة وطابق الشعور مع الفعل.","items":[{"q":"In the poem, what does the child do when happy?","answer":"laughs and plays","explanation":"Line 1.","explanation_ar":"يضحك ويلعب.","options":["counts to ten","rests his head","tells his dad","laughs and plays"],"dok":1,"skill":"feelings and actions","text_id":"TXT-RW-L02-U1-LS3-1","stage":"controlled"},{"q":"What does the child need when sad?","answer":"a friend","explanation":"Line 3: I need a friend.","explanation_ar":"صديقًا.","options":["a toy","a friend","a bed","a kite"],"dok":1,"skill":"feelings and actions","stage":"controlled"},{"q":"What does the child do when angry?","answer":"counts to ten","explanation":"Line 5.","explanation_ar":"يعدّ إلى عشرة.","options":["laughs and plays","shares toys","goes to bed","counts to ten"],"dok":1,"skill":"feelings and actions","stage":"controlled"},{"q":"Who does the child tell when scared?","answer":"Dad","explanation":"Line 7: I tell my dad.","explanation_ar":"الأب.","options":["the teacher","a friend","Dad","Grandma"],"dok":1,"skill":"feelings and actions","stage":"controlled"},{"q":"What happens to the child's cheeks when excited?","answer":"They go red.","explanation":"Line 10.","explanation_ar":"يحمرّ الخدان.","options":["They go white.","They get cold.","They go red.","They feel tired."],"dok":1,"skill":"feelings and actions","stage":"controlled"},{"q":"What does the child do when tired?","answer":"rests his head","explanation":"Line 9.","explanation_ar":"يريح رأسه.","options":["rests his head","counts to ten","laughs","shares toys"],"dok":1,"skill":"feelings and actions","stage":"controlled"}]},{"id":"RW-L02-U1-LS3-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Characters in *The Broken Kite*. Choose the answer.","instructions_ar":"الشخصيات في قصة الطائرة المكسورة: اختر الإجابة.","items":[{"q":"Which action shows that Sami feels sorry?","answer":"He says, \"I am sorry, Omar.\"","explanation":"His words show he is sorry.","explanation_ar":"كلماته تدل على أسفه.","options":["He runs home.","He laughs.","He says, \"I am sorry, Omar.\"","He buys a kite."],"dok":1,"skill":"character words","stage":"guided"},{"q":"Which clue shows that Sami is sad?","answer":"His eyes are full of tears.","explanation":"Tears show sadness.","explanation_ar":"الدموع.","options":["He holds the string.","His eyes are full of tears.","He goes to the park.","He fixes the kite."],"dok":1,"skill":"character clues","stage":"guided"},{"q":"What does Omar do when he feels angry?","answer":"He takes a deep breath.","explanation":"Text: Omar takes a deep breath.","explanation_ar":"يأخذ نفسًا عميقًا.","options":["He shouts at Sami.","He takes a deep breath.","He breaks the string.","He goes home."],"dok":1,"skill":"character actions","stage":"guided"},{"q":"How do Omar's feelings change?","answer":"excited → angry → kind","explanation":"Follow Omar through the story.","explanation_ar":"تتغير مشاعره.","options":["sad → scared → tired","happy → happy → happy","angry → excited → sad","excited → angry → kind"],"dok":2,"skill":"character change","stage":"guided"},{"q":"Which line in the poem is like Omar's action?","answer":"I take a breath, then talk again.","explanation":"Both take a breath when angry.","explanation_ar":"كلاهما يأخذ نفسًا.","options":["I take a breath, then talk again.","I rest my head.","My cheeks go red!","I share my toys."],"dok":2,"skill":"connect texts","stage":"guided"},{"q":"What is the same in the story and the poem?","answer":"Both show good actions for feelings.","explanation":"Both connect feelings and actions.","explanation_ar":"كلاهما يربط المشاعر بالأفعال.","options":["Both show good actions for feelings.","Both have a red kite.","Both are in a park.","Both have Dad."],"dok":2,"skill":"compare","stage":"guided"}]},{"id":"RW-L02-U1-LS3-A3","type":"organizer","stage":"freer","instructions":"Organizer: Complete the Feelings Map for the poem.","instructions_ar":"أكمل خريطة المشاعر للقصيدة.","items":[{"q":"happy → What does the child do?","answer":"laughs, plays and shares toys","explanation":"Line 1–2.","explanation_ar":"السطران 1–2.","dok":1,"skill":"feelings map","stage":"freer"},{"q":"sad → What does the child need?","answer":"a friend, a kind word and help","explanation":"Lines 3–4.","explanation_ar":"السطران 3–4.","dok":1,"skill":"feelings map","stage":"freer"},{"q":"angry → What does the child do?","answer":"counts to ten and takes a breath","explanation":"Lines 5–6.","explanation_ar":"السطران 5–6.","dok":1,"skill":"feelings map","stage":"freer"},{"q":"scared → What does the child do?","answer":"tells his dad","explanation":"Line 7.","explanation_ar":"السطر 7.","dok":1,"skill":"feelings map","stage":"freer"}]},{"id":"RW-L02-U1-LS3-A4","type":"open","stage":"production","instructions":"Writing: Write about feelings and actions.","instructions_ar":"اكتب عن المشاعر والأفعال.","items":[{"q":"When you feel angry, what can you do? Write a sentence.","answer":"When I feel angry, I take a deep breath.","explanation":"When I feel ___, I ___.","explanation_ar":"When I feel ___, I ___.","dok":2,"skill":"connect","stage":"production"},{"q":"How can you help a sad friend?","answer":"I can sit with him and say a kind word.","explanation":"A kind action.","explanation_ar":"تصرف لطيف.","dok":2,"skill":"connect","stage":"production"},{"q":"Write a new line for the poem: When I feel ___, I ___.","answer":"When I feel brave, I try something new.","explanation":"Feeling + action.","explanation_ar":"شعور + فعل.","dok":2,"skill":"creative writing","stage":"production"},{"q":"How does Omar feel at the end of *The Broken Kite*? What does he do?","answer":"He feels happy. He laughs and runs with Sami.","explanation":"Feeling + action from the text.","explanation_ar":"شعور + فعل من النص.","dok":2,"skill":"character feelings","stage":"production"}]},{"id":"RW-L02-U1-LS3-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"When I Feel…\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “When I Feel…”.","answer":"91 words","title":"When I Feel…","body":"When I feel happy, I laugh and play.\n\nI share my toys with friends all day.\n\nWhen I feel sad, I need a friend,\n\na kind word and a hand to lend.\n\nWhen I feel angry, I count to ten.\n\nI take a breath, then talk again.\n\nWhen I feel scared, I tell my dad,\n\nand soon I am not scared or sad.\n\nWhen I feel tired, I rest my head.\n\nWhen I'm excited, my cheeks go red!\n\nEvery feeling is OK, you see.\n\nAll my feelings are part of me!","words":91,"limit":114}],"time_limit_sec":114},{"id":"RW-L02-U1-LS3-ORG","type":"organizer","organizer":"Feelings Map","instructions":"Organizer: For each feeling, write what the character does or says and the clue from the text.","items":[{"q":"Feeling: happy → action","answer":"I laugh and play."},{"q":"Feeling: angry → action","answer":"I count to ten and take a breath."},{"q":"Feeling: scared → action","answer":"I tell my dad."},{"q":"Feeling: excited → action","answer":"My cheeks go red."}]}],"game":{"name":"Feelings Freeze Dance","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Feeling-action match: a feeling face appears; the child drags it to the action picture that fits from the poem. A second round asks for a 'good choice' action for angry and scared.","Students walk while the music plays.","When it stops, the teacher shows a feeling card (e.g., angry).","Students freeze in a helpful action for that feeling (counting to ten, taking a breath).","The teacher asks two students to say the sentence: \"When I feel angry, I count to ten.\"","Play 8 rounds."],"data":[]},"exit_quiz":[{"q":"Actions and words show us a character's ___.","answer":"feelings","explanation":"They show feelings.","explanation_ar":"تدل على المشاعر.","options":["address","title","feelings","age"],"dok":1,"skill":"strategy"},{"q":"In the poem, *I count to ten* goes with which feeling?","answer":"angry","explanation":"Line 5.","explanation_ar":"الغضب.","options":["happy","tired","angry","excited"],"dok":1,"skill":"feelings and actions"},{"q":"In the poem, *I need a friend* goes with which feeling?","answer":"sad","explanation":"Line 3.","explanation_ar":"الحزن.","options":["excited","angry","happy","sad"],"dok":1,"skill":"feelings and actions"},{"q":"What is the poem's message?","answer":"Every feeling is OK.","explanation":"Line 11.","explanation_ar":"كل المشاعر مقبولة.","options":["Never feel angry.","Every feeling is OK.","Kites are fun.","Dads are tall."],"dok":2,"skill":"theme"},{"q":"Which word rhymes with *friend* in the poem?","answer":"lend","explanation":"friend/lend.","explanation_ar":"friend وlend.","options":["ten","red","dad","lend"],"dok":1,"skill":"rhyme"},{"q":"Which action is a GOOD choice when you feel angry?","answer":"take a deep breath","explanation":"Breathing helps us calm down.","explanation_ar":"التنفس يهدئنا.","options":["shout at a friend","break a toy","push someone","take a deep breath"],"dok":2,"skill":"connect"},{"q":"*Badr is brave at the dentist.* *Brave* means ___.","answer":"not afraid to do something hard","explanation":"Brave = not afraid.","explanation_ar":"شجاع.","options":["not afraid to do something hard","very tired","very angry","very sad"],"dok":1,"skill":"vocabulary"},{"q":"Which clue tells you Omar is calm again?","answer":"He says, \"It is OK.\"","explanation":"Kind words show he is calm.","explanation_ar":"كلماته الهادئة.","options":["The kite breaks.","The wind is strong.","He says, \"It is OK.\"","Sami holds the string."],"dok":2,"skill":"character clues"},{"q":"How are Omar and the child in the poem the SAME?","answer":"Both take a breath when angry.","explanation":"Both calm down with a breath.","explanation_ar":"كلاهما يتنفس بعمق عند الغضب.","options":["Both take a breath when angry.","Both fly kites.","Both have red cheeks.","Both go to bed."],"dok":3,"skill":"compare"},{"q":"Why does the poet say *All my feelings are part of me*?","answer":"to show that all feelings are normal","explanation":"Feelings are normal parts of us.","explanation_ar":"المشاعر طبيعية.","options":["to say feelings are bad","to show that all feelings are normal","to talk about the weather","to tell a story about a kite"],"dok":3,"skill":"author's message"}],"images":[{"id":"IMG-RW-L02-U1-LS3-V01","prompt":"Picture for the word 'count': fingers counting one to ten"},{"id":"IMG-RW-L02-U1-LS3-V02","prompt":"Picture for the word 'breath': a child breathing in with eyes closed"},{"id":"IMG-RW-L02-U1-LS3-V03","prompt":"Picture for the word 'brave': a boy smiling bravely in a dentist's chair"},{"id":"IMG-RW-L02-U1-LS3-V04","prompt":"Picture for the word 'rest': a girl resting on a cushion"},{"id":"IMG-RW-L02-U1-LS3-V05","prompt":"Picture for the word 'cheeks': a smiling face with rosy cheeks"},{"id":"IMG-RW-L02-U1-LS3-V06","prompt":"Picture for the word 'action': a child jumping, with motion lines"},{"id":"IMG-RW-L02-U1-LS3-V07","prompt":"Picture for the word 'OK': a thumbs-up sign"},{"id":"IMG-RW-L02-U1-LS3-01","prompt":"Layla shows six feelings and what she does for each."},{"id":"IMG-RW-L02-U1-LS3-02","prompt":"Four arrows from feeling faces to empty action boxes."},{"id":"IMG-RW-L02-U1-LS3-03","prompt":"Omar's face changes from excited to angry to kind."}],"audio":[{"id":"AUD-RW-L02-U1-LS3-V01","script":"count. Count to ten slowly."},{"id":"AUD-RW-L02-U1-LS3-V02","script":"breath. Take a deep breath."},{"id":"AUD-RW-L02-U1-LS3-V03","script":"brave. Badr is brave at the dentist."},{"id":"AUD-RW-L02-U1-LS3-V04","script":"rest. Rest after you run."},{"id":"AUD-RW-L02-U1-LS3-V05","script":"cheeks. Her cheeks are pink."},{"id":"AUD-RW-L02-U1-LS3-V06","script":"action. Laughing is a happy action."},{"id":"AUD-RW-L02-U1-LS3-V07","script":"OK. Is everything OK?"},{"id":"AUD-RW-L02-U1-LS3-T1","script":"When I feel happy, I laugh and play. I share my toys with friends all day. When I feel sad, I need a friend, a kind word and a hand to lend. When I feel angry, I count to ten. I take a breath, then talk again. When I feel scared, I tell my dad, and soon I am not scared or sad. When I feel tired, I rest my head. When I'm excited, my cheeks go red! Every feeling is OK, you see. All my feelings are part of me!"},{"id":"AUD-RW-L02-U1-LS3-VID","script":"Feelings and actions go together. What do YOU do when you feel happy? When I feel happy, I laugh and play… Look: angry → count to ten. Scared → tell my dad. The action shows the feeling! In The Broken Kite, Omar feels excited, then angry, then kind. His feelings change! Every feeling is OK. What we DO with our feelings is important."}]},{"id":"RW-L02-U1-LS4","title":"Writing Skill: Sentences with because","lesson_type":"writing_skill","objectives":["write sentences that give a reason with *because*","answer *Why?* questions with a full *because* sentence","avoid writing *because* sentences that are not complete"],"objectives_ar":["كتابة جمل تذكر السبب باستخدام because.","الإجابة عن أسئلة Why بجملة كاملة فيها because.","تجنب كتابة جمل because غير مكتملة."],"success_criteria":["I can answer a Why question with because.","I can write feeling + because + reason.","I can check that my because sentence is complete."],"success_criteria_ar":["أستطيع الإجابة عن سؤال Why باستخدام because.","أستطيع كتابة: شعور + because + سبب.","أستطيع التحقق من اكتمال جملة because."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"because","pos":"conjunction","ipa":"/bɪˈkɔz/","definition":"a joining word that gives a reason","arabic":"لأن","example":"I am happy because it is Friday.","image_id":"IMG-RW-L02-U1-LS4-V01","audio_id":"AUD-RW-L02-U1-LS4-V01","tier":"core"},{"word":"why","pos":"adverb","ipa":"/waɪ/","definition":"a question word that asks for a reason","arabic":"لماذا","example":"Why are you sad?","image_id":"IMG-RW-L02-U1-LS4-V02","audio_id":"AUD-RW-L02-U1-LS4-V02","tier":"core"},{"word":"reason","pos":"noun","ipa":"/ˈrizən/","definition":"why something happens","arabic":"سبب","example":"What is the reason?","image_id":"IMG-RW-L02-U1-LS4-V03","audio_id":"AUD-RW-L02-U1-LS4-V03","tier":"core"},{"word":"proud","pos":"adjective","ipa":"/praʊd/","definition":"happy about something good you or others did","arabic":"فخور","example":"Dad is proud of my work.","image_id":"IMG-RW-L02-U1-LS4-V04","audio_id":"AUD-RW-L02-U1-LS4-V04","tier":"core"},{"word":"bored","pos":"adjective","ipa":"/bɔrd/","definition":"not interested; with nothing fun to do","arabic":"يشعر بالملل","example":"I am bored because it is raining.","image_id":"IMG-RW-L02-U1-LS4-V05","audio_id":"AUD-RW-L02-U1-LS4-V05","tier":"core"},{"word":"worried","pos":"adjective","ipa":"/ˈwɝid/","definition":"thinking that something bad may happen","arabic":"قلق","example":"Huda is worried about the test.","image_id":"IMG-RW-L02-U1-LS4-V06","audio_id":"AUD-RW-L02-U1-LS4-V06","tier":"core"},{"word":"calm","pos":"adjective","ipa":"/kɑm/","definition":"quiet and not worried or angry","arabic":"هادئ","example":"Take a breath and stay calm.","image_id":"IMG-RW-L02-U1-LS4-V07","audio_id":"AUD-RW-L02-U1-LS4-V07","tier":"core"}],"explanation":{"text":"**Because** gives a **reason**. It answers the question **Why?**\n\nPattern: **feeling or action + because + reason.** *I am happy **because** it is Friday.*\n\nAfter *because*, write a **full idea** with a who and an action word: *because **I have** a new book* – not *because new book*.\n\nDo not write *because…* alone as a sentence. Join it to the first part.","examples":["Why is Sami sad? → **Sami is sad because the kite is broken.**","Why is Omar excited? → **Omar is excited because he has a new kite.**","Why is Lama scared? → **Lama is scared because the room is dark.**","**I am tired because I play football every afternoon.**","**Mother is proud because I help at home.**","**Faris is bored because he has nothing to do.**","**Huda is worried because the test is tomorrow.**","**I am calm because I take a deep breath.**","**We laugh because the story is funny.**"],"common_errors":["✗ I am happy. Because it is Friday. → ✓ I am happy because it is Friday. (Join *because* to the first part.)","✗ I am sad because my kite broken. → ✓ I am sad because my kite is broken. (After *because*, use a full idea with **is**.)","✗ I am happy because of it is Eid. → ✓ I am happy because it is Eid. (Use **because** (not *because of*) before a sentence.)","✗ I am tired, because I play. → ✓ I am tired because I play. (No comma before *because* here.)","✗ Because I am hungry I eat. → ✓ I eat because I am hungry. (Start with the main part (it is easier and clearer).)","✗ Why you are sad? → ✓ Why are you sad? (In questions, put **are** before *you*.)","✗ He is worry. → ✓ He is worried. (Feeling word = **worried**.)"],"arabic":"كلمة because تعني \"لأن\" وتذكر السبب، وتجيب عن سؤال Why (لماذا).\n\nالنمط: شعور أو فعل + because + سبب، مثل: I am happy because it is Friday.\n\nبعد because اكتب فكرة كاملة فيها فاعل وفعل: because I have a new book، وليس because new book.\n\nلا تكتب جملة تبدأ بـ because وحدها؛ اربطها بالجزء الأول. ولا نضع فاصلة قبل because في هذه الجمل."},"video":{"script":[{"time":"00:00–00:15","narration":"Why? Why? Why? When someone asks why, we answer with BECAUSE!","on_screen":"Why? → because","visual":"Saqr asks 'Why?' with a big question mark; the word 'because' appears like a bridge."},{"time":"00:15–00:50","narration":"Sami is sad… why? Because the kite is broken!","on_screen":"Sami is sad + because + the kite is broken.","visual":"Two sentence parts join with a 'because' bridge."},{"time":"00:50–01:20","narration":"Feeling, because, reason. I am happy because my friend is here.","on_screen":"feeling + because + reason","visual":"Three colored blocks line up: blue (feeling), gold (because), green (reason)."},{"time":"01:20–01:50","narration":"Oops! 'Because new book.' That is not complete. Add a who and an action: because I have a new book!","on_screen":"because new book ✗ → because I have a new book ✓","visual":"Missing pieces fly into the reason block."},{"time":"01:50–02:15","narration":"Don't leave because alone! 'Because it is Friday.' Join it: I am happy because it is Friday.","on_screen":"Join it! 🔗","visual":"A lonely 'because' sentence walks over and joins the first part."},{"time":"02:15–02:40","narration":"Now answer: Why are YOU happy today?","on_screen":"I am happy because…","visual":"Noura holds her notebook and smiles."}],"captions_ar":["لماذا؟ لماذا؟ عندما يسألك أحد لماذا نجيب بـ because!","سامي حزين… لماذا؟ لأن الطائرة مكسورة!","شعور + لأن + سبب: أنا سعيد لأن صديقي هنا.","انتبه! because new book غير مكتملة. أضف فاعلًا وفعلًا: because I have a new book!","لا تترك because وحدها؛ اربطها: I am happy because it is Friday.","والآن أجب: لماذا أنت سعيد اليوم؟"],"voice":"Narrator: American English, warm female teacher, speed 0.85. Noura: thoughtful girl. A 'why?' sound (rising chime) before each reason."},"texts":[{"type":"model","title":"Why I Feel… (from Noura's Notebook)","body":"I am happy because my friend Layla is here. I feel tired because we play football for an hour.\n\nLama is scared because the room is dark. Omar is excited because he has a new kite. My mother is proud because I help at home.","word_count":45,"audio_id":"AUD-RW-L02-U1-LS4-T1","id":"TXT-RW-L02-U1-LS4-1","genre":"model text","role":"model","difficulty":"200L–350L","glossary":[],"annotations":["**I am happy** – the first part tells the FEELING.","**because my friend Layla is here** – the second part gives the REASON (it answers *Why?*).","After **because**, write a full idea with a who and an action word: *because **we play***.","There is **no comma** before *because* in these sentences.","One sentence = feeling + because + reason."]}],"activities":[{"id":"RW-L02-U1-LS4-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the best reason to finish the sentence.","instructions_ar":"اختر أفضل سبب لإكمال الجملة.","items":[{"q":"Reem is sad because ___.","answer":"her cat is sick","explanation":"A sick cat is a sad reason.","explanation_ar":"القطة مريضة سبب للحزن.","options":["her cat is sick","she is happy","the sun is nice","she has a gift"],"dok":1,"skill":"reasons","stage":"controlled"},{"q":"Majed is tired because ___.","answer":"he runs all afternoon","explanation":"Running a lot makes you tired.","explanation_ar":"الجري يتعب.","options":["he is excited","it is Eid","he runs all afternoon","he has a new book"],"dok":1,"skill":"reasons","stage":"controlled"},{"q":"Lama is scared because ___.","answer":"there is a loud noise","explanation":"Loud noises can scare us.","explanation_ar":"الأصوات العالية تخيف.","options":["there is a loud noise","she has a new doll","it is a sunny day","she eats dates"],"dok":1,"skill":"reasons","stage":"controlled"},{"q":"Badr is proud because ___.","answer":"he wins a prize","explanation":"Winning makes us proud.","explanation_ar":"الفوز يجعلنا فخورين.","options":["he loses his bag","he wins a prize","he is sleepy","the room is dark"],"dok":1,"skill":"reasons","stage":"controlled"},{"q":"Faris is bored because ___.","answer":"he has nothing to do","explanation":"Nothing to do = bored.","explanation_ar":"لا شيء يفعله.","options":["he plays with friends","he reads a funny book","he goes to the park","he has nothing to do"],"dok":1,"skill":"reasons","stage":"controlled"},{"q":"Huda is worried because ___.","answer":"her brother is late","explanation":"Waiting for someone late can worry us.","explanation_ar":"تأخر أخيها يقلقها.","options":["she has a party","her brother is late","she eats lunch","she is glad"],"dok":2,"skill":"reasons","stage":"controlled"}]},{"id":"RW-L02-U1-LS4-A2","type":"open","stage":"guided","instructions":"Guided practice: Join the two parts with *because*. Write one sentence.","instructions_ar":"اربط الجزأين بـ because في جملة واحدة.","items":[{"q":"I am happy. / It is Friday.","answer":"I am happy because it is Friday.","explanation":"Feeling + because + reason.","explanation_ar":"شعور + because + سبب.","dok":1,"skill":"joining with because","stage":"guided"},{"q":"Omar is excited. / He has a new kite.","answer":"Omar is excited because he has a new kite.","explanation":"Join with because.","explanation_ar":"اربط بـ because.","dok":1,"skill":"joining with because","stage":"guided"},{"q":"We laugh. / The story is funny.","answer":"We laugh because the story is funny.","explanation":"Join with because.","explanation_ar":"اربط بـ because.","dok":1,"skill":"joining with because","stage":"guided"},{"q":"Sami says sorry. / The kite is broken.","answer":"Sami says sorry because the kite is broken.","explanation":"Join with because.","explanation_ar":"اربط بـ because.","dok":2,"skill":"joining with because","stage":"guided"},{"q":"Mother is proud. / I help at home.","answer":"Mother is proud because I help at home.","explanation":"Join with because.","explanation_ar":"اربط بـ because.","dok":1,"skill":"joining with because","stage":"guided"},{"q":"I am calm. / I take a deep breath.","answer":"I am calm because I take a deep breath.","explanation":"Join with because.","explanation_ar":"اربط بـ because.","dok":2,"skill":"joining with because","stage":"guided"}]},{"id":"RW-L02-U1-LS4-A3","type":"open","stage":"freer","instructions":"Freer practice: Fix the because sentences.","instructions_ar":"صحّح جمل because.","items":[{"q":"I am happy. Because my cousins are here.","answer":"I am happy because my cousins are here.","explanation":"Join the two parts.","explanation_ar":"اربط الجزأين.","dok":2,"skill":"editing","stage":"freer"},{"q":"Sami is sad because kite broken.","answer":"Sami is sad because the kite is broken.","explanation":"Add the and is.","explanation_ar":"أضف the وis.","dok":2,"skill":"editing","stage":"freer"},{"q":"I am tired because of I play.","answer":"I am tired because I play.","explanation":"Use because, not because of.","explanation_ar":"استخدم because وليس because of.","dok":2,"skill":"editing","stage":"freer"},{"q":"Why you are worried?","answer":"Why are you worried?","explanation":"Question order: Why are you…?","explanation_ar":"ترتيب السؤال.","dok":2,"skill":"editing","stage":"freer"}]},{"id":"RW-L02-U1-LS4-A4","type":"open","stage":"production","instructions":"Writing: Write about YOU. Use *because*.","instructions_ar":"اكتب عن نفسك مستخدمًا because.","items":[{"q":"Why are you happy today?","answer":"I am happy because my friend shares his snack.","explanation":"I am happy because + full reason.","explanation_ar":"سبب كامل.","dok":1,"skill":"writing","stage":"production"},{"q":"When are you tired? Why?","answer":"I am tired after school because I wake up early.","explanation":"Feeling + because + reason.","explanation_ar":"شعور + سبب.","dok":2,"skill":"writing","stage":"production"},{"q":"Why is your friend a good friend?","answer":"Fahad is a good friend because he helps me.","explanation":"Name + because + reason.","explanation_ar":"اسم + سبب.","dok":2,"skill":"writing","stage":"production"},{"q":"Write a sentence with *proud* and *because*.","answer":"I am proud because I can read in English.","explanation":"proud + because.","explanation_ar":"proud + because.","dok":2,"skill":"writing","stage":"production"}]}],"game":{"name":"Because Bridge","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Bridge builder: a feeling part is on the left bank and reasons float on the river; the child drags the right reason across the 'because' bridge. Complete sentences are read aloud. Incomplete reasons (no verb) sink!","Each pair gets 8 feeling cards and 8 reason cards, mixed.","They match each feeling with a reason that makes sense, with the because card in the middle.","They read each sentence aloud.","The teacher checks two sentences per pair; each correct one = 1 point.","Bonus: find the two reason cards that are NOT complete and fix them."],"data":[]},"exit_quiz":[{"q":"*Because* gives a ___.","answer":"reason","explanation":"Because = reason.","explanation_ar":"because تذكر السبب.","options":["name","reason","place","color"],"dok":1,"skill":"rule"},{"q":"Which question do we answer with *because*?","answer":"Why?","explanation":"Why asks for a reason.","explanation_ar":"Why.","options":["Why?","Who?","Where?","When?"],"dok":1,"skill":"rule"},{"q":"Which sentence is complete?","answer":"I am happy because it is Eid.","explanation":"Feeling + because + full reason.","explanation_ar":"مكتملة.","options":["I am happy because it is Eid.","Because it is Eid.","I am happy because Eid.","Because happy."],"dok":1,"skill":"complete sentences"},{"q":"Which reason is complete?","answer":"because the room is dark","explanation":"It has a who (the room) and *is*.","explanation_ar":"فيها فاعل وفعل.","options":["because dark room","because the room dark","because is dark","because the room is dark"],"dok":2,"skill":"complete reasons"},{"q":"Finish: *Dad is proud because ___.*","answer":"I help my brother","explanation":"Helping makes Dad proud.","explanation_ar":"المساعدة تجعله فخورًا.","options":["I help my brother","I am sad","the room is dark","it is cold"],"dok":1,"skill":"reasons"},{"q":"*Faris has nothing to do. He is ___.*","answer":"bored","explanation":"Nothing to do = bored.","explanation_ar":"يشعر بالملل.","options":["proud","calm","bored","brave"],"dok":1,"skill":"vocabulary"},{"q":"Which sentence uses *worried* correctly?","answer":"Huda is worried because her test is tomorrow.","explanation":"Feeling word + complete reason.","explanation_ar":"استخدام صحيح.","options":["Huda is worry because her test.","Huda worried test tomorrow.","Because worried Huda.","Huda is worried because her test is tomorrow."],"dok":2,"skill":"usage"},{"q":"Where do we put a comma in *I am tired because I play*?","answer":"We do not need a comma.","explanation":"No comma before because here.","explanation_ar":"لا نحتاج فاصلة.","options":["after tired","We do not need a comma.","after because","after I"],"dok":2,"skill":"punctuation"},{"q":"Fix: *I am happy because of my friend is here.*","answer":"I am happy because my friend is here.","explanation":"Use because + sentence.","explanation_ar":"because + جملة.","options":["I am happy because of friend here.","Because my friend is here.","I am happy because my friend is here.","I am happy of my friend."],"dok":2,"skill":"editing"},{"q":"Which answer to *Why is Omar kind to Sami?* is best?","answer":"Omar is kind because he knows it was the wind.","explanation":"It is complete and uses the story.","explanation_ar":"إجابة كاملة من القصة.","options":["Because wind.","Omar is kind because he knows it was the wind.","Omar is kind.","The kite."],"dok":3,"skill":"reasons with evidence"}],"images":[{"id":"IMG-RW-L02-U1-LS4-V01","prompt":"Picture for the word 'because': a speech bubble with an arrow pointing to a reason picture"},{"id":"IMG-RW-L02-U1-LS4-V02","prompt":"Picture for the word 'why': a big question mark with a curious child"},{"id":"IMG-RW-L02-U1-LS4-V03","prompt":"Picture for the word 'reason': a child pointing to a broken toy to explain"},{"id":"IMG-RW-L02-U1-LS4-V04","prompt":"Picture for the word 'proud': a father smiling at his son's certificate"},{"id":"IMG-RW-L02-U1-LS4-V05","prompt":"Picture for the word 'bored': a boy sitting with his chin in his hands looking out of a window"},{"id":"IMG-RW-L02-U1-LS4-V06","prompt":"Picture for the word 'worried': a girl biting her lip, holding a test paper"},{"id":"IMG-RW-L02-U1-LS4-V07","prompt":"Picture for the word 'calm': a boy sitting peacefully with eyes closed"},{"id":"IMG-RW-L02-U1-LS4-01","prompt":"Noura's notebook with doodles of different feelings."},{"id":"IMG-RW-L02-U1-LS4-02","prompt":"A golden bridge joining a blue block and a green block."},{"id":"IMG-RW-L02-U1-LS4-03","prompt":"A three-color sentence strip."}],"audio":[{"id":"AUD-RW-L02-U1-LS4-V01","script":"because. I am happy because it is Friday."},{"id":"AUD-RW-L02-U1-LS4-V02","script":"why. Why are you sad?"},{"id":"AUD-RW-L02-U1-LS4-V03","script":"reason. What is the reason?"},{"id":"AUD-RW-L02-U1-LS4-V04","script":"proud. Dad is proud of my work."},{"id":"AUD-RW-L02-U1-LS4-V05","script":"bored. I am bored because it is raining."},{"id":"AUD-RW-L02-U1-LS4-V06","script":"worried. Huda is worried about the test."},{"id":"AUD-RW-L02-U1-LS4-V07","script":"calm. Take a breath and stay calm."},{"id":"AUD-RW-L02-U1-LS4-T1","script":"I am happy because my friend Layla is here. I feel tired because we play football for an hour. Lama is scared because the room is dark. Omar is excited because he has a new kite. My mother is proud because I help at home."},{"id":"AUD-RW-L02-U1-LS4-VID","script":"Why? Why? Why? When someone asks why, we answer with BECAUSE! Sami is sad… why? Because the kite is broken! Feeling, because, reason. I am happy because my friend is here. Oops! 'Because new book.' That is not complete. Add a who and an action: because I have a new book! Don't leave because alone! 'Because it is Friday.' Join it: I am happy because it is Friday. Now answer: Why are YOU happy today?"}]},{"id":"RW-L02-U1-LS5","title":"Writing Workshop: A Good Friend","lesson_type":"writing_workshop","objectives":["plan 5 sentences about a good friend with three reasons","write an opening sentence, three because sentences and a closing sentence","revise with a feeling word or synonym, edit, and publish on the Friendship Wall"],"objectives_ar":["التخطيط لخمس جمل عن صديق جيد مع ثلاثة أسباب.","كتابة جملة افتتاحية وثلاث جمل بـ because وجملة ختامية.","التحسين بكلمة شعور أو مرادف، والتدقيق، والنشر على جدار الصداقة."],"success_criteria":["I can plan reasons why my friend is good.","I can write 5 sentences with because.","I can check that every because sentence is complete."],"success_criteria_ar":["أستطيع التخطيط لأسباب كون صديقي جيدًا.","أستطيع كتابة 5 جمل باستخدام because.","أستطيع التحقق من اكتمال كل جملة بـ because."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"best friend","pos":"noun","ipa":"/bɛst frɛnd/","definition":"the friend you like the most","arabic":"أعز صديق","example":"Majed is my best friend.","image_id":"IMG-RW-L02-U1-LS5-V01","audio_id":"AUD-RW-L02-U1-LS5-V01","tier":"core"},{"word":"helpful","pos":"adjective","ipa":"/ˈhɛlpfəl/","definition":"ready to help others","arabic":"متعاون / يساعد","example":"My friend is helpful in class.","image_id":"IMG-RW-L02-U1-LS5-V02","audio_id":"AUD-RW-L02-U1-LS5-V02","tier":"core"},{"word":"polite","pos":"adjective","ipa":"/pəˈlaɪt/","definition":"using kind words like please and thank you","arabic":"مهذب","example":"Badr is polite to everyone.","image_id":"IMG-RW-L02-U1-LS5-V03","audio_id":"AUD-RW-L02-U1-LS5-V03","tier":"core"},{"word":"honest","pos":"adjective","ipa":"/ˈɑnəst/","definition":"always telling the truth","arabic":"صادق / أمين","example":"An honest friend tells the truth.","image_id":"IMG-RW-L02-U1-LS5-V04","audio_id":"AUD-RW-L02-U1-LS5-V04","tier":"core"},{"word":"trust","pos":"verb","ipa":"/trʌst/","definition":"to believe someone is good and honest","arabic":"يثق بـ","example":"I trust my best friend.","image_id":"IMG-RW-L02-U1-LS5-V05","audio_id":"AUD-RW-L02-U1-LS5-V05","tier":"core"},{"word":"cheer up","pos":"verb","ipa":"/tʃɪr ʌp/","definition":"to make a sad person happy again","arabic":"يُبهج / يرفع المعنويات","example":"Omar cheers me up with a joke.","image_id":"IMG-RW-L02-U1-LS5-V06","audio_id":"AUD-RW-L02-U1-LS5-V06","tier":"core"},{"word":"promise","pos":"verb","ipa":"/ˈprɑmɪs/","definition":"to say you will really do something","arabic":"يَعِد","example":"I promise to help you.","image_id":"IMG-RW-L02-U1-LS5-V07","audio_id":"AUD-RW-L02-U1-LS5-V07","tier":"core"}],"explanation":{"text":"Today you write **5 sentences** about a good friend.\n\n**1. Opening:** *My best friend is ___.* **2–4. Three reasons** with *because*: *He is a good friend because he ___.* **5. Closing:** *I am happy because ___ is my friend.*\n\nUse **feeling words** and **synonyms** from this unit: kind, helpful, honest, glad, cheer up.","examples":["Opening: **My best friend is Fahad.**","Opening: **Noura is a good friend.**","Reason: **He is a good friend because he shares his snacks.**","Reason: **She is kind because she cheers me up when I am sad.**","Reason: **I trust him because he is honest.**","Reason: **He is polite because he says please and thank you.**","Reason: **We are good friends because we play together every day.**","Closing: **I am glad because Fahad is my friend.**","Revise: *He is nice.* → **He is kind and helpful.**"],"common_errors":["✗ My best friend he is Fahad. → ✓ My best friend is Fahad. (One subject only.)","✗ He is good friend. → ✓ He is a good friend. (Use **a** before good friend.)","✗ Because he shares. → ✓ He is a good friend because he shares. (Join because to the first part.)","✗ She cheer me up. → ✓ She cheers me up. (One person → **cheers**.)","✗ He is very honesty. → ✓ He is very honest. (Use the describing word **honest**.)","✗ I trust on him. → ✓ I trust him. (No **on** after trust.)"],"arabic":"اليوم تكتب 5 جمل عن صديق جيد.\n\n1- جملة افتتاحية: My best friend is ___. 2-4- ثلاثة أسباب بـ because. 5- جملة ختامية: I am happy because ___ is my friend.\n\nاستخدم كلمات المشاعر والمرادفات من الوحدة مثل kind, helpful, honest, glad.\n\nانتبه: نقول I trust him ولا نقول I trust on him، ونقول He is a good friend بإضافة a."},"video":{"script":[{"time":"00:00–00:15","narration":"What makes a good friend? Sami writes about Omar.","on_screen":"A Good Friend","visual":"Sami at his desk with a photo of him and Omar flying the kite."},{"time":"00:15–00:45","narration":"Plan: Sami thinks of three reasons: Omar shares, forgives and cheers him up.","on_screen":"1 Plan – 3 reasons","visual":"Three hearts appear with icons: sharing, a handshake, a laughing face."},{"time":"00:45–01:30","narration":"Draft: My best friend is Omar. He is a good friend because he shares his kite. He is kind because he forgives me. He cheers me up because he tells funny jokes. I am glad because Omar is my friend.","on_screen":"2 Draft – opening · 3 reasons · closing","visual":"Five sentence strips stack up: blue, three green, blue."},{"time":"01:30–01:55","narration":"Revise: 'He is nice' becomes 'He is kind and honest.'","on_screen":"3 Revise ➕ better words","visual":"Plain word 'nice' swaps for 'kind and honest' with a sparkle."},{"time":"01:55–02:20","narration":"Edit: Is every because sentence complete? Who and action after because? Check!","on_screen":"4 Edit ✔ because","visual":"Each 'because' part lights up green when complete."},{"time":"02:20–02:50","narration":"Publish: Sami puts his page on the Friendship Wall. Omar reads it and smiles!","on_screen":"5 Publish 💛","visual":"A colorful Friendship Wall with heart-shaped pages; Omar smiles."}],"captions_ar":["ما الذي يجعل الصديق جيدًا؟ سامي يكتب عن عمر.","التخطيط: يفكر سامي في ثلاثة أسباب: عمر يشاركه ويسامحه ويُبهجه.","المسودة: أعز أصدقائي عمر. هو صديق جيد لأنه يشاركني طائرته. هو لطيف لأنه يسامحني. يُبهجني لأنه يروي نكتًا مضحكة. أنا سعيد لأن عمر صديقي.","التحسين: \"هو لطيف\" تصبح \"هو طيب وصادق\".","التدقيق: هل كل جملة بـ because مكتملة؟ فاعل وفعل بعدها؟","النشر: يضع سامي صفحته على جدار الصداقة، فيقرؤها عمر ويبتسم!"],"voice":"Narrator: American English, warm female teacher, speed 0.85. Sami: thoughtful boy reading his page about Omar."},"texts":[],"activities":[{"id":"RW-L02-U1-LS5-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the best answer.","instructions_ar":"اختر أفضل إجابة.","items":[{"q":"A friend who always tells the truth is ___.","answer":"honest","explanation":"Honest = tells the truth.","explanation_ar":"صادق.","options":["bored","honest","tired","worried"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"A friend who says please and thank you is ___.","answer":"polite","explanation":"Polite = kind words.","explanation_ar":"مهذب.","options":["polite","angry","scared","bored"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Omar tells a joke to a sad friend. He ___ his friend.","answer":"cheers up","explanation":"Making a sad friend happy = cheer up.","explanation_ar":"يُبهجه.","options":["forgives","trusts","promises","cheers up"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Which is a good opening sentence about a friend?","answer":"My best friend is Turki.","explanation":"It names the friend.","explanation_ar":"تذكر اسم الصديق.","options":["Because he helps me.","I am glad.","My best friend is Turki.","The end."],"dok":1,"skill":"structure","stage":"controlled"},{"q":"Which is a good closing sentence?","answer":"I am glad because Turki is my friend.","explanation":"It ends with a feeling.","explanation_ar":"تختم بشعور.","options":["My best friend is Turki.","Turki.","Because he shares.","I am glad because Turki is my friend."],"dok":1,"skill":"structure","stage":"controlled"},{"q":"Which word is better than *nice* in *He is nice*?","answer":"helpful","explanation":"Helpful tells more.","explanation_ar":"helpful أدق.","options":["sad","bored","helpful","worried"],"dok":2,"skill":"word choice","stage":"controlled"}]},{"id":"RW-L02-U1-LS5-A2","type":"sequence","stage":"guided","instructions":"Put in order: Put the words in order to make a reason sentence.","instructions_ar":"رتّب الكلمات لتكوين جملة سبب.","items":[{"q":"Build a reason sentence about sharing.","answer":"He is a good friend because he shares.","explanation":"Feeling/description + because + reason.","explanation_ar":"وصف + because + سبب.","stage":"guided","parts":["He","he","a","because","friend","is","good","shares."],"target":["He","is","a","good","friend","because","he","shares."]},{"q":"Build a reason sentence about cheering up.","answer":"She is kind because she cheers me up.","explanation":"kind + because + reason.","explanation_ar":"kind + because + سبب.","stage":"guided","parts":["cheers","up.","me","because","she","She","is","kind"],"target":["She","is","kind","because","she","cheers","me","up."]},{"q":"Build a reason sentence about trust.","answer":"I trust him because he is honest.","explanation":"trust + because + reason.","explanation_ar":"trust + because + سبب.","stage":"guided","parts":["because","trust","him","I","honest.","is","he"],"target":["I","trust","him","because","he","is","honest."]},{"q":"Build an opening sentence about Ziad.","answer":"My best friend is Ziad.","explanation":"Opening sentence.","explanation_ar":"جملة افتتاحية.","stage":"guided","parts":["is","My","friend","best","Ziad."],"target":["My","best","friend","is","Ziad."]},{"q":"Build a closing sentence about Ziad.","answer":"I am glad because Ziad is my friend.","explanation":"Closing sentence.","explanation_ar":"جملة ختامية.","stage":"guided","parts":["friend.","Ziad","is","glad","am","my","because","I"],"target":["I","am","glad","because","Ziad","is","my","friend."]},{"q":"Build a reason sentence about playing together.","answer":"We are friends because we play together.","explanation":"Reason with together.","explanation_ar":"سبب مع together.","stage":"guided","parts":["friends","We","together.","are","play","we","because"],"target":["We","are","friends","because","we","play","together."]}]},{"id":"RW-L02-U1-LS5-A3","type":"organizer","stage":"freer","instructions":"Organizer: Plan your writing. Fill in the Friendship Reasons Plan.","instructions_ar":"خطط لكتابتك.","items":[{"q":"My friend's name:","answer":"Hamad","explanation":"A real friend's name.","explanation_ar":"اسم صديق حقيقي.","dok":1,"skill":"planning","stage":"freer"},{"q":"Reason 1: He/She is a good friend because…","answer":"he helps me with math","explanation":"A complete reason.","explanation_ar":"سبب كامل.","dok":2,"skill":"planning","stage":"freer"},{"q":"Reason 2: …because…","answer":"he is honest","explanation":"A different reason.","explanation_ar":"سبب مختلف.","dok":2,"skill":"planning","stage":"freer"},{"q":"Reason 3: …because…","answer":"he cheers me up","explanation":"A third reason.","explanation_ar":"سبب ثالث.","dok":2,"skill":"planning","stage":"freer"}]},{"id":"RW-L02-U1-LS5-A4","type":"writing","stage":"production","instructions":"Writing: Write your 5 sentences. Then edit and publish.","instructions_ar":"اكتب جملك الخمس ثم دققها وانشرها.","items":[{"q":"Write your opening sentence about your friend.","answer":"My best friend is Hamad.","explanation":"Name + is.","explanation_ar":"الاسم.","dok":1,"skill":"writing","stage":"production"},{"q":"Write your three reason sentences with because.","answer":"He is a good friend because he helps me with math. I trust him because he is honest. He cheers me up because he is funny.","explanation":"Three complete because sentences.","explanation_ar":"ثلاث جمل كاملة.","dok":2,"skill":"writing","stage":"production"},{"q":"Write your closing sentence.","answer":"I am happy because Hamad is my friend.","explanation":"Feeling + because + friend.","explanation_ar":"شعور + سبب.","dok":1,"skill":"writing","stage":"production"},{"q":"Which reason did your partner like best?","answer":"He liked 'he helps me with math'.","explanation":"One reason.","explanation_ar":"سبب واحد.","dok":2,"skill":"sharing","stage":"production","_w":{"checklist":[],"min":null,"max":null}}]},{"id":"RW-L02-U1-LS5-ORG","type":"organizer","organizer":"Friendship Reasons Plan","instructions":"Organizer: Write your friend's name in the heart. Write three reasons in the boxes.","items":[{"q":"My friend's name","answer":"Omar"},{"q":"Reason 1 (because…)","answer":"he shares his kite"},{"q":"Reason 2 (because…)","answer":"he forgives me"},{"q":"Reason 3 (because…)","answer":"he cheers me up with jokes"}]},{"id":"RW-L02-U1-LS5-WR","type":"writing","instructions":"Writing: Write 5 sentences about a good friend: an opening sentence, three reasons with because and a closing sentence. Write 5 sentences about a good friend: an opening sentence, three reasons with because and a closing sentence.","instructions_ar":"اكتب 5 جمل عن صديق جيد: جملة افتتاحية، وثلاثة أسباب بـ because، وجملة ختامية.","prompt":"Write 5 sentences about a good friend: an opening sentence, three reasons with because and a closing sentence.","checklist":["I wrote an opening sentence with my friend's name.","I wrote three reasons with because.","After because, I wrote a who and an action word.","I wrote a closing sentence.","I used one feeling word or synonym (kind, glad, honest…).","Capitals, periods and spaces are correct."],"rubric_id":"RW-RUBRIC-5T","min_words":30,"max_words":80,"organizer":"Friendship Reasons Plan (name – three reasons)","items":[{"q":"Write 5 sentences about a good friend: an opening sentence, three reasons with because and a closing sentence.","answer":"My best friend is Omar. He is a good friend because he shares his kite with me. He is kind because he forgives me. He cheers me up because he tells funny jokes. I am glad because Omar is my friend.","_w":{"checklist":["I wrote an opening sentence with my friend's name.","I wrote three reasons with because.","After because, I wrote a who and an action word.","I wrote a closing sentence.","I used one feeling word or synonym (kind, glad, honest…).","Capitals, periods and spaces are correct."],"min":30,"max":80}}]}],"game":{"name":"Friendship Recipe","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Recipe mixer: the child drags quality 'ingredients' into a bowl; for each one, he types or records a because sentence (A good friend is honest because…). Five ingredients complete the recipe and bake a 'friendship cake'.","Each team gets 5 ingredient cards.","A player takes a card and makes a sentence: \"A good friend is kind because he helps you.\"","If the because part is complete, the card goes in the bowl.","Each correct ingredient = 1 point.","The team with a full bowl first wins and reads its recipe aloud."],"data":[]},"exit_quiz":[{"q":"How many sentences do you write about your friend?","answer":"five","explanation":"Five sentences.","explanation_ar":"خمس جمل.","options":["two","ten","one","five"],"dok":1,"skill":"task"},{"q":"What comes FIRST in your writing?","answer":"the opening sentence","explanation":"The opening sentence is first.","explanation_ar":"الجملة الافتتاحية.","options":["the closing sentence","the opening sentence","the reasons","the checklist"],"dok":1,"skill":"structure"},{"q":"How many reasons do you give?","answer":"three","explanation":"Three reasons.","explanation_ar":"ثلاثة أسباب.","options":["one","three","five","none"],"dok":1,"skill":"structure"},{"q":"Which sentence is a complete reason?","answer":"He is a good friend because he helps me.","explanation":"Feeling + because + full reason.","explanation_ar":"سبب كامل.","options":["Because he helps me.","He is a good friend because helps.","He is a good friend because he helps me.","He helps because."],"dok":2,"skill":"complete sentences"},{"q":"*I trust him.* *Trust* means ___.","answer":"believe he is good and honest","explanation":"Trust = believe in someone.","explanation_ar":"يثق.","options":["run with him","believe he is good and honest","forget him","draw him"],"dok":1,"skill":"vocabulary"},{"q":"Which word means *always tells the truth*?","answer":"honest","explanation":"Honest = truthful.","explanation_ar":"صادق.","options":["honest","polite","bored","proud"],"dok":1,"skill":"vocabulary"},{"q":"Fix: *I trust on my friend.*","answer":"I trust my friend.","explanation":"No *on* after trust.","explanation_ar":"لا on بعد trust.","options":["I trust in on my friend.","I trusting my friend.","I am trust my friend.","I trust my friend."],"dok":2,"skill":"editing"},{"q":"Which word is the best change for *nice* in *She is nice*?","answer":"kind","explanation":"Kind is more exact.","explanation_ar":"kind أدق.","options":["angry","tired","bored","kind"],"dok":2,"skill":"word choice"},{"q":"Which closing sentence uses a synonym for *happy*?","answer":"I am glad because Huda is my friend.","explanation":"Glad = happy.","explanation_ar":"glad مرادف happy.","options":["I am sad because Huda is my friend.","Huda is my friend.","I am glad because Huda is my friend.","I am mad because Huda is my friend."],"dok":2,"skill":"synonyms"},{"q":"Which writing about a friend is the BEST?","answer":"an opening, three complete because reasons and a closing","explanation":"It has all the parts.","explanation_ar":"فيها كل الأجزاء.","options":["an opening, three complete because reasons and a closing","one sentence only","three reasons with no because","a list of names"],"dok":3,"skill":"evaluate"}],"images":[{"id":"IMG-RW-L02-U1-LS5-V01","prompt":"Picture for the word 'best friend': two boys smiling with arms around shoulders"},{"id":"IMG-RW-L02-U1-LS5-V02","prompt":"Picture for the word 'helpful': a girl helping a friend with homework"},{"id":"IMG-RW-L02-U1-LS5-V03","prompt":"Picture for the word 'polite': a boy holding a door open for a teacher"},{"id":"IMG-RW-L02-U1-LS5-V04","prompt":"Picture for the word 'honest': a child returning a found wallet to a man"},{"id":"IMG-RW-L02-U1-LS5-V05","prompt":"Picture for the word 'trust': two friends sharing a secret note, smiling"},{"id":"IMG-RW-L02-U1-LS5-V06","prompt":"Picture for the word 'cheer up': a boy making a sad friend laugh"},{"id":"IMG-RW-L02-U1-LS5-V07","prompt":"Picture for the word 'promise': two children doing a pinky promise"},{"id":"IMG-RW-L02-U1-LS5-01","prompt":"A Friendship Wall full of heart pages; Omar smiles at Sami's page."},{"id":"IMG-RW-L02-U1-LS5-02","prompt":"A heart in the middle with three boxes around it."},{"id":"IMG-RW-L02-U1-LS5-03","prompt":"Cards falling into a mixing bowl."}],"audio":[{"id":"AUD-RW-L02-U1-LS5-V01","script":"best friend. Majed is my best friend."},{"id":"AUD-RW-L02-U1-LS5-V02","script":"helpful. My friend is helpful in class."},{"id":"AUD-RW-L02-U1-LS5-V03","script":"polite. Badr is polite to everyone."},{"id":"AUD-RW-L02-U1-LS5-V04","script":"honest. An honest friend tells the truth."},{"id":"AUD-RW-L02-U1-LS5-V05","script":"trust. I trust my best friend."},{"id":"AUD-RW-L02-U1-LS5-V06","script":"cheer up. Omar cheers me up with a joke."},{"id":"AUD-RW-L02-U1-LS5-V07","script":"promise. I promise to help you."},{"id":"AUD-RW-L02-U1-LS5-VID","script":"What makes a good friend? Sami writes about Omar. Plan: Sami thinks of three reasons: Omar shares, forgives and cheers him up. Draft: My best friend is Omar. He is a good friend because he shares his kite. He is kind because he forgives me. He cheers me up because he tells funny jokes. I am glad because Omar is my friend. Revise: 'He is nice' becomes 'He is kind and honest.' Edit: Is every because sentence complete? Who and action after because? Check! Publish: Sami puts his page on the Friendship Wall. Omar reads it and smiles!"}]}],"unit_test":[{"q":"Rakan gives half of his cake to his sister. He ___ his cake.","answer":"shares","explanation":"Giving part = sharing.","explanation_ar":"يتشارك.","options":["laughs","hides","shares","breaks"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"A loud storm makes the baby ___.","answer":"scared","explanation":"Storms can scare babies.","explanation_ar":"خائف.","options":["scared","glad","proud","polite"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"Which word means the same as *mad*?","answer":"angry","explanation":"Mad = angry.","explanation_ar":"angry.","options":["happy","calm","tired","angry"],"dok":1,"skill":"synonyms","_part":"Part A – Words"},{"q":"Tomorrow is our school trip! I am so ___.","answer":"excited","explanation":"A trip makes us excited.","explanation_ar":"متحمس.","options":["bored","sorry","tired","excited"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"I stepped on your foot. I am ___.","answer":"sorry","explanation":"We say sorry for mistakes.","explanation_ar":"آسف.","options":["proud","brave","sorry","excited"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"Which word means the same as *afraid*?","answer":"scared","explanation":"Afraid = scared.","explanation_ar":"scared.","options":["scared","glad","kind","bored"],"dok":1,"skill":"synonyms","_part":"Part A – Words"},{"q":"Mona always tells the truth. She is ___.","answer":"honest","explanation":"Truthful = honest.","explanation_ar":"صادقة.","options":["bored","honest","worried","tired"],"dok":2,"skill":"vocabulary in context","_part":"Part A – Words"},{"q":"Saleh helps old people carry their bags. He is very ___.","answer":"helpful","explanation":"Helping = helpful.","explanation_ar":"متعاون.","options":["angry","helpful","bored","scared"],"dok":2,"skill":"vocabulary in context","_part":"Part A – Words"},{"q":"Which because sentence is complete?","answer":"Layla is happy because she has new friends.","explanation":"Feeling + because + full reason.","explanation_ar":"كاملة.","options":["Because she has new friends.","Layla is happy because new friends.","Layla happy because.","Layla is happy because she has new friends."],"dok":1,"skill":"complete sentences","_part":"Part D – Check the sentences"},{"q":"Which question is written correctly?","answer":"Why is Layla shy?","explanation":"Why + is + subject.","explanation_ar":"Why + is + الفاعل.","options":["Why Layla is shy?","Why shy is Layla?","Why is Layla shy?","Layla why is shy?"],"dok":2,"skill":"questions","_part":"Part D – Check the sentences"},{"q":"Which pair are NOT synonyms?","answer":"happy – worried","explanation":"Happy and worried are different.","explanation_ar":"ليستا مترادفتين.","options":["happy – worried","glad – happy","afraid – scared","angry – mad"],"dok":2,"skill":"synonyms","_part":"Part D – Check the sentences"},{"q":"Which sentence about Huda's drawing is correct?","answer":"Huda feels proud of her drawing.","explanation":"feels + feeling word.","explanation_ar":"feels + شعور.","options":["Huda is feel proud.","Huda feels proud of her drawing.","Huda proud feel.","Huda feeling proud of."],"dok":2,"skill":"usage","_part":"Part D – Check the sentences"},{"q":"Which question is best to ask DURING reading *Layla's First Day*?","answer":"Will someone talk to Layla?","explanation":"During reading we wonder what will happen next.","explanation_ar":"أثناء القراءة نتساءل عما سيحدث.","options":["What is the title?","Will someone talk to Layla?","What did I learn from the whole story?","Who wrote the cover?"],"dok":2,"skill":"asking questions","_part":"Part D – Check the sentences"}],"unit_writing":{"task":"Write 5 sentences about a time you felt happy or proud. Use because in at least two sentences.","model":"Last week, I felt very proud. My teacher gave me a star because I read a whole book. My father was happy because I worked hard. I smiled all day. I am proud because I can read in English.","marks":20}});
